let _be = null, _key = "";
function be(){
  const c = DD.config || {}, live = c.mode === "live" && c.url && c.anonKey, key = live ? c.url : "demo";
  if(key !== _key){ _be = live ? liveBackend(c) : demoBackend(); _key = key; }
  return _be;
}
const isLive = () => _key !== "demo" && !!_key;

