function css(){ if(!document.getElementById("dd-reviews-css")) document.head.append(h("style", {id:"dd-reviews-css"}, CSS)); }

/* ---------- модалки, подтверждение, тост ---------- */
function modal(title, build){
  css();
  const opener = document.activeElement, t = h("h3", {id:uid("t")}, title);
  const d = h("dialog", {class:"dd dd-dlg", "aria-labelledby":t.id});
  const close = () => d.close();
  d.append(h("div", {class:"dd-in"}, h("button", {class:"dd-btn dd-x", type:"button", "aria-label":tx("close"), onclick:close}, "×"), t, build(close, d)));
  d.addEventListener("click", e => { if(e.target === d) close(); });   // клик по подложке
  d.addEventListener("close", () => { d.remove(); if(opener && opener.isConnected && opener.focus) opener.focus(); });
  document.body.append(d); d.showModal();   // <dialog>: фокус внутри, Esc закрывает, фон inert
  return d;
}
const ask = text => new Promise(ok => {
  let yes = false;
  const d = modal(text, close => h("div", {class:"dd-actions"},
    h("button", {class:"dd-btn danger", type:"button", onclick:() => { yes = true; close(); }}, tx("confirm")),
    h("button", {class:"dd-btn quiet", type:"button", onclick:close}, tx("cancel"))));
  d.addEventListener("close", () => ok(yes));
});
function say(text){
  if(typeof window.toast === "function") return window.toast(text);
  css(); document.querySelectorAll(".dd-toast").forEach(x => x.remove());
  const el = h("div", {class:"dd-toast", role:"status"}, text); document.body.append(el); setTimeout(() => el.remove(), 3200);
}
/* силуэт вместо первой буквы, если имя начинается не с буквы или цифры (раньше в шапке появлялось «<») */
const USER_SVG = '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8.5" r="3.6"/><path d="M4.8 20c.9-3.6 3.7-5.6 7.2-5.6s6.3 2 7.2 5.6"/></svg>';
function userIcon(cls){ const s = h("span", {class:cls || "dd-uicon", "aria-hidden":"true"}); s.innerHTML = USER_SVG; return s; }
function ava(u, big){
  const src = safeUrl(u.avatar), cls = "dd-ava" + (big ? " lg" : "");
  if(src) return h("img", {class:cls, src, alt:"", loading:"lazy"});
  const ch = [...String(u.name || u.nickname || "").trim()][0] || "";
  return /[\p{L}\p{N}]/u.test(ch) ? h("span", {class:cls, "aria-hidden":"true"}, ch) : userIcon(cls + " dd-ava-ic");
}
function lightbox(p, r){
  const nick = r.user.nickname;
  modal(tx("photoBy", {n:nick}), () => [h("div", {class:"dd-lb"}, h("img", {src:safeUrl(p.url), alt:tx("photoBy", {n:nick})})), shareRow(r, p)]);
}

/* ---------- поделиться и карточка для сторис ---------- */
const recipeUrl = rid => location.href.split("#")[0] + "#recipe=" + encodeURIComponent(rid);
const shareRow = (r, p) => h("div", {class:"dd-actions"},
  h("button", {class:"dd-btn", type:"button", onclick:act(() => share(r.recipeId, r, p))}, tx("share")),
  h("button", {class:"dd-btn quiet", type:"button", onclick:act(() => saveStory(r.recipeId, r, p, "storySaved"))}, tx("story")));
async function share(rid, r, p){
  const url = recipeUrl(rid), text = r ? tx("shareText", {d:dishName(rid), s:r.rating, n:r.user.nickname}) : tx("shareCooked", {d:dishName(rid)});
  p = p || (r && r.photos[0]);
  if(navigator.share){
    try {
      const blob = p && safeUrl(p.url) ? await fetch(p.url).then(x => x.blob()).catch(() => null) : null;
      const file = blob && new File([blob], `dishday-${rid}.${blob.type === "image/webp" ? "webp" : "jpg"}`, {type:blob.type || "image/jpeg"});
      await navigator.share(file && navigator.canShare && navigator.canShare({files:[file]}) ? {title:"Dishday", text, url, files:[file]} : {title:"Dishday", text, url});
      return;
    } catch(e){ if(e && e.name === "AbortError") return; }
  }
  let copied = false;
  try { await navigator.clipboard.writeText(`${text} ${url}`); copied = true; } catch(e){}
  await saveStory(rid, r, p, copied ? "linkCopied" : "storySaved");
}
async function saveStory(rid, r, p, note){
  const b = await storyBlob(rid, r, p), href = URL.createObjectURL(b), a = h("a", {href, download:`dishday-${rid}-story.png`, hidden:true});
  document.body.append(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(href), 5000);
  say(tx(note));
}
const loadImg = src => new Promise((ok, no) => { const i = new Image(); if(/^https:/.test(src)) i.crossOrigin = "anonymous"; i.onload = () => ok(i); i.onerror = no; i.src = src; });
function wrapText(g, text, max, lines){
  const out = []; let cur = "";
  for(const w of String(text).split(/\s+/)){ const next = cur ? cur + " " + w : w; if(!cur || g.measureText(next).width <= max) cur = next; else { out.push(cur); cur = w; } }
  if(cur) out.push(cur);
  if(out.length > lines){ out.length = lines; out[lines - 1] += "..."; }
  return out;
}
/* 1080x1920: фото блюда, название, оценка, ник, знак Dishday. Фото из Supabase грузится с CORS, иначе canvas не отдаст картинку */
async function storyBlob(rid, r, p){
  const W = 1080, H = 1920, X = 90, Y = 200, PW = 900, PH = 1040;
  const c = h("canvas", {width:W, height:H}), g = c.getContext("2d");
  try { await document.fonts.ready; } catch(e){}
  g.fillStyle = "#05070F"; g.fillRect(0, 0, W, H);
  for(const [x, y, rad, col] of [[160, 240, 760, "rgba(139,124,246,.42)"], [980, 1560, 860, "rgba(110,231,249,.26)"], [900, 380, 520, "rgba(240,168,208,.2)"]]){
    const gr = g.createRadialGradient(x, y, 0, x, y, rad); gr.addColorStop(0, col); gr.addColorStop(1, "rgba(5,7,15,0)"); g.fillStyle = gr; g.fillRect(0, 0, W, H);
  }
  const src = safeUrl(p && p.url) || dishPhoto(rid), img = src ? await loadImg(src).catch(() => null) : null;
  g.save(); g.beginPath(); g.roundRect(X, Y, PW, PH, 56); g.clip();
  if(img){ const k = Math.max(PW / img.width, PH / img.height), w = img.width * k, hh = img.height * k; g.drawImage(img, X + (PW - w) / 2, Y + (PH - hh) / 2, w, hh); }
  else { const gr = g.createLinearGradient(X, Y, X + PW, Y + PH); gr.addColorStop(0, "#6EE7F9"); gr.addColorStop(.55, "#8B7CF6"); gr.addColorStop(1, "#F0A8D0"); g.fillStyle = gr; g.fillRect(X, Y, PW, PH); }
  g.restore();
  g.strokeStyle = "rgba(170,190,255,.26)"; g.lineWidth = 3; g.beginPath(); g.roundRect(X, Y, PW, PH, 56); g.stroke();
  let y = Y + PH + 130;
  g.fillStyle = "#F3F5FC"; g.font = '600 70px Unbounded, Onest, sans-serif';
  for(const line of wrapText(g, dishName(rid), PW, 2)){ g.fillText(line, X, y); y += 90; }
  if(r){
    g.fillStyle = "#FFC857"; g.font = '64px Onest, sans-serif'; g.fillText("★".repeat(r.rating) + "☆".repeat(5 - r.rating), X, y + 6);
    g.fillStyle = "#AEB8D6"; g.font = '600 40px Onest, sans-serif'; g.fillText(`${tx(r.worth ? "worthYes" : "worthNo")} · @${r.user.nickname}`, X, y + 86);
  }
  const by = H - 130;
  g.save(); g.translate(X, by - 76); g.scale(1.3, 1.3); g.lineCap = "round"; g.strokeStyle = "#F3F5FC";
  g.lineWidth = 5.5; g.beginPath(); g.arc(32, 45, 22, Math.PI, 2 * Math.PI); g.stroke();
  g.lineWidth = 5; g.beginPath(); g.moveTo(6, 51); g.lineTo(58, 51); g.stroke();
  g.fillStyle = "#6EE7F9"; g.beginPath(); g.arc(32, 16.5, 4.8, 0, 2 * Math.PI); g.fill(); g.restore();
  g.fillStyle = "#F3F5FC"; g.font = '600 54px Unbounded, Onest, sans-serif'; g.fillText("Dishday", X + 110, by - 12);
  g.fillStyle = "#AEB8D6"; g.font = '500 38px Onest, sans-serif'; g.fillText("Dinner, decided.", X + 110, by + 42);
  return new Promise((ok, no) => c.toBlob(b => b ? ok(b) : no(err("err")), "image/png"));
}

/* ---------- экран «Приготовлено!» после режима готовки ---------- */
function openCooked(rid){
  modal(tx("cookedT"), close => [
    h("p", {class:"dd-lead", style:"margin-top:8px;font-weight:600"}, dishName(rid)),
    h("p", {class:"dd-note", style:"margin-top:6px"}, tx("cookedP")),
    h("div", {class:"dd-actions"},
      h("button", {class:"dd-btn main", type:"button", onclick:() => { close(); openForm(rid); }}, tx("reviewPhoto")),
      h("button", {class:"dd-btn", type:"button", onclick:act(() => share(rid))}, tx("share")),
      h("button", {class:"dd-btn quiet", type:"button", onclick:close}, tx("later")))
  ]);
}
const SOCIAL_KEY = "dd_social_default";
const socialDefault = () => { try { return localStorage.getItem(SOCIAL_KEY) === "1"; } catch(e){ return false; } };

/* ---------- обновление открытых лент и профиля ---------- */
const views = new Map();
function refresh(){
  for(const [el, fn] of views){ if(el.isConnected) fn(); else views.delete(el); }
  document.dispatchEvent(new CustomEvent("dd-reviews:change"));   // приложение обновляет свои бейджи оценок
}
async function guard(then){
  let s = null; try { s = await be().session(); } catch(e){ say(msg(e)); return; }
  if(s) return then(); openSignIn(then);
}
const act = fn => async function(){ this.disabled = true; try { await fn(); } catch(e){ if(e.code === "auth") openSignIn(); else say(msg(e)); } finally { this.disabled = false; } };

/* ---------- вход ---------- */
const field = (label, input, hint) => { input.id = uid("f"); if(hint) input.setAttribute("aria-describedby", hint.id = uid("h")); return h("div", {class:"dd-field"}, h("label", {class:"dd-label", for:input.id}, label), input, hint); };

/* официальная кнопка Google Identity Services. Google получает SHA-256 от nonce, Supabase - сам nonce (так требует signInWithIdToken) */
let gsiP = null;
const loadGsi = () => gsiP || (gsiP = new Promise((ok, no) => {
  if(window.google && google.accounts && google.accounts.id) return ok();
  const s = h("script", {src:"https://accounts.google.com/gsi/client", async:true}); s.onload = ok; s.onerror = () => { gsiP = null; no(err("err")); };
  document.head.append(s);
}));
const hex = buf => [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, "0")).join("");
async function googleButton(box, onCred){
  await loadGsi();
  const nonce = hex(crypto.getRandomValues(new Uint8Array(24))), hashed = hex(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(nonce)));
  google.accounts.id.initialize({client_id:authCfg().googleClientId, nonce:hashed, ux_mode:"popup", auto_select:false, use_fedcm_for_button:true, callback:r => onCred({token:r.credential, nonce})});
  google.accounts.id.renderButton(box, {theme:"filled_black", size:"large", shape:"pill", text:"continue_with", logo_alignment:"center", width:Math.min(400, Math.max(220, box.clientWidth || 300)), locale:lang() ? "en" : "ru"});
}

/* вход нужен только для публикации: отзыв, комментарий, жалоба, профиль */
function openSignIn(then, rid){
  const live = isLive();
  if(rid) try { sessionStorage.setItem("dd_after", rid); } catch(e){}
  modal(tx("signTitle"), close => {
    const alert = h("p", {class:"dd-alert", role:"alert"});
    const warn = (text, good) => { alert.className = "dd-alert" + (good ? " ok" : ""); alert.textContent = text; };
    const done = () => { try { sessionStorage.removeItem("dd_after"); } catch(e){} close(); refresh(); if(then) then(); };
    const why = h("p", {class:"dd-note"}, tx("signWhy"));
    if(!live){
      const name = h("input", {type:"text", maxlength:"60", autocomplete:"name"});
      const nick = h("input", {type:"text", maxlength:"24", autocapitalize:"none", spellcheck:"false", placeholder:"cook_name"});
      return [h("div", {class:"dd-demo", role:"note"}, h("b", {}, tx("demoTitle")), h("span", {}, tx("demoNote"))), why,
        h("form", {novalidate:true, onsubmit:async e => {
          e.preventDefault(); const nk = nick.value.trim().toLowerCase();
          if(!NICK_RE.test(nk)){ warn(tx("nickHint")); nick.focus(); return; }
          try { await be().signIn("demo", {name:name.value.trim().slice(0, 60), nickname:nk}); done(); } catch(x){ warn(msg(x)); }
        }}, field(tx("name"), name), field(tx("nick"), nick, h("p", {class:"dd-note"}, tx("nickHint"))), alert,
          h("div", {class:"dd-actions"}, h("button", {class:"dd-btn main", type:"submit"}, tx("demoIn"))))];
    }
    let pending = null;
    const xb = h("input", {type:"checkbox"}), em = h("input", {type:"email", id:uid("em"), autocomplete:"email", required:true, inputmode:"email"});
    const ok = () => { if(xb.checked) return true; warn(tx("needXb")); xb.focus(); return false; };
    const idToken = async cred => { try { await be().signIn("idtoken", cred); done(); } catch(x){ warn(msg(x)); } };
    xb.addEventListener("change", () => { if(!xb.checked) return; warn(""); if(pending){ const p = pending; pending = null; idToken(p); } });
    const oauth = () => h("button", {class:"dd-btn main", type:"button", onclick:act(async () => { if(ok()) await be().signIn("google"); })}, tx("google"));
    const gbox = h("div", {class:"dd-gsi"});
    if(authCfg().googleClientId) requestAnimationFrame(() => googleButton(gbox, cred => { if(ok()) idToken(cred); else pending = cred; }).catch(() => fill(gbox, oauth())));
    else gbox.append(oauth());
    return [why, h("label", {class:"dd-check"}, xb, h("span", {}, tx("xb"))), gbox,
      h("p", {class:"dd-or"}, tx("or")),
      h("form", {class:"dd-field", novalidate:true, onsubmit:async e => {
        e.preventDefault(); if(!ok()) return;
        if(!em.checkValidity()){ warn(tx("badEmail")); em.focus(); return; }
        try { await be().signIn("email", {email:em.value.trim()}); warn(tx("magicSent"), true); } catch(x){ warn(msg(x)); }
      }}, h("label", {class:"dd-label", for:em.id}, tx("email")), em, h("button", {class:"dd-btn", type:"submit"}, tx("emailLink"))),
      alert];
  });
}

/* ---------- форма отзыва ---------- */
async function openForm(rid){
  let s; try { s = await be().session(); } catch(e){ return say(msg(e)); }
  if(!s) return openSignIn(() => openForm(rid), rid);
  let mine; try { mine = (await be().list(rid)).find(r => r.mine); } catch(e){ return say(msg(e)); }
  const st = {rating:mine ? mine.rating : 0, worth:mine ? mine.worth : null, keep:mine ? mine.photos.slice() : [], drop:[], added:[]};
  modal(tx("formTitle"), close => {
    const alert = h("p", {class:"dd-alert", role:"alert"});
    const count = () => st.keep.length + st.added.length;
    const file = h("input", {type:"file", accept:"image/*", multiple:true, hidden:true, onchange:async () => {
      alert.textContent = "";
      for(const f of [...file.files]){ if(count() >= MAX_PHOTOS) break; try { const b = await shrink(f, 1280); st.added.push({b, url:URL.createObjectURL(b)}); } catch(e){ alert.textContent = msg(e); } }
      file.value = ""; draw();
    }});
    const thumbs = h("div", {class:"dd-thumbs"});
    const thumb = (url, n, remove) => h("div", {class:"dd-thumb"}, h("img", {src:safeUrl(url), alt:""}), h("button", {type:"button", "aria-label":tx("removePhoto", {n}), onclick:remove}, h("span", {"aria-hidden":"true"}, "×")));
    function draw(){
      let n = 0;
      fill(thumbs,
        ...st.keep.map((p, i) => thumb(p.url, ++n, () => { st.drop.push(p.path); st.keep.splice(i, 1); draw(); })),
        ...st.added.map((x, i) => thumb(x.url, ++n, () => { URL.revokeObjectURL(x.url); st.added.splice(i, 1); draw(); })),
        count() < MAX_PHOTOS ? h("button", {class:"dd-add", type:"button", "aria-label":tx("addPhoto"), onclick:() => file.click()}, "+") : null);
    }
    draw();
    const group = uid("g");
    const stars = [1, 2, 3, 4, 5].map(n => { const id = uid("s"); return [h("input", {type:"radio", name:group + "r", id, value:String(n), checked:st.rating === n, onchange:() => { st.rating = n; paint(); }}), h("label", {for:id, class:"dd-star"}, h("span", {"aria-hidden":"true"}, "★"), h("span", {class:"dd-sr"}, tx("starOf", {n})))]; });
    const paint = () => stars.forEach(([, l], i) => l.classList.toggle("on", i < st.rating));
    paint();
    const pill = (val, label) => { const id = uid("w"); return [h("input", {type:"radio", name:group + "w", id, checked:st.worth === val, onchange:() => { st.worth = val; }}), h("label", {for:id, class:"dd-pill"}, label)]; };
    const ta = h("textarea", {id:uid("b"), maxlength:String(MAX_BODY), placeholder:tx("bodyPh")}, mine ? mine.body : "");
    const counter = h("span", {class:"dd-note", "aria-live":"polite"}, `${ta.value.length}/${MAX_BODY}`);
    ta.addEventListener("input", () => { counter.textContent = `${ta.value.length}/${MAX_BODY}`; });
    const social = h("input", {type:"checkbox", checked:mine ? mine.socialOk : socialDefault()});
    const submit = h("button", {class:"dd-btn main", type:"submit"}, tx(mine ? "save" : "publish"));
    return h("form", {novalidate:true, onsubmit:async e => {
      e.preventDefault();
      if(!st.rating || st.worth === null){ alert.textContent = tx("needRating"); return; }
      submit.disabled = true; alert.textContent = "";
      try {
        const res = await be().saveReview({id:mine && mine.id, recipeId:rid, cc:(window.DD_REGION || {}).cc, cuisine:(recipe(rid) || {}).cu, rating:st.rating, worth:st.worth, body:ta.value.trim().slice(0, MAX_BODY),
          socialOk:social.checked, consentChanged:!mine || mine.socialOk !== social.checked, drop:st.drop, blobs:st.added.map(x => x.b)});
        st.added.forEach(x => URL.revokeObjectURL(x.url)); close(); refresh(); say(tx(res.bonus ? "bonus" : "saved"));
      } catch(x){ if(x.code === "auth"){ close(); openSignIn(() => openForm(rid), rid); } else alert.textContent = msg(x); }
      finally { submit.disabled = false; }
    }},
      h("p", {class:"dd-note"}, dishName(rid)),
      h("div", {class:"dd-field"}, h("span", {class:"dd-label"}, tx("photos")), thumbs, file, h("p", {class:"dd-note"}, tx("photosHint"))),
      h("fieldset", {class:"dd-field"}, h("legend", {}, tx("rating")), h("div", {class:"dd-opt"}, stars)),
      h("fieldset", {class:"dd-field"}, h("legend", {}, tx("worth")), h("div", {class:"dd-opt"}, pill(true, tx("yes")), pill(false, tx("no")))),
      h("div", {class:"dd-field"}, h("label", {class:"dd-label", for:ta.id}, tx("body")), ta, counter),
      h("label", {class:"dd-check"}, social, h("span", {}, tx("social"), h("br"), h("span", {class:"dd-note"}, tx("socialNote")))),
      alert,
      h("div", {class:"dd-actions"}, submit,
        mine ? null : h("button", {class:"dd-btn quiet", type:"button", onclick:act(async () => { await be().markCooked(rid, (recipe(rid) || {}).cu); close(); refresh(); say(tx("marked")); })}, tx("justMark")))
    );
  });
}

/* ---------- лента ---------- */
const openComments = new Set();
function reviewCard(r, opt){
  const who = h("div", {class:"dd-who"}, ava(r.user), h("div", {},
    h("b", {}, "@" + r.user.nickname), r.mine ? h("span", {class:"dd-meta"}, ` (${tx("you")})`) : null,
    h("div", {class:"dd-meta"}, opt.dish ? [dishName(r.recipeId), " · "] : null, date(r.created))));
  const shareBtn = h("button", {class:"dd-btn quiet", type:"button", onclick:act(() => share(r.recipeId, r))}, tx("share"));
  const actions = r.mine
    ? [shareBtn, h("button", {class:"dd-btn quiet", type:"button", onclick:() => openForm(r.recipeId)}, tx("edit")),
       h("button", {class:"dd-btn quiet", type:"button", onclick:act(async () => { if(await ask(tx("delQ"))){ await be().deleteReview(r.id); refresh(); } })}, tx("del"))]
    : [shareBtn, h("button", {class:"dd-btn quiet", type:"button", disabled:r.reported, onclick:() => guard(async () => { if(await ask(tx("reportQ"))){ try { await be().report("review", r.id); say(tx("reported")); refresh(); } catch(e){ say(msg(e)); } } })}, tx(r.reported ? "reported" : "report"))];
  let comments = null;
  if(opt.comments){
    const input = h("input", {type:"text", maxlength:String(MAX_COMMENT), "aria-label":tx("commentPh"), placeholder:tx("commentPh")});
    comments = h("details", {open:openComments.has(r.id), ontoggle:e => e.target.open ? openComments.add(r.id) : openComments.delete(r.id)},
      h("summary", {}, tx("comments", {n:r.comments.length})),
      r.comments.map(c => h("div", {class:"dd-com"},
        h("div", {class:"dd-who"}, ava(c.user), h("div", {}, h("b", {}, "@" + c.user.nickname), h("span", {class:"dd-meta"}, " · " + date(c.created)))),
        c.hidden ? h("p", {class:"dd-hid"}, tx("hiddenNote")) : null,
        h("p", {class:"dd-body"}, c.body),
        h("div", {class:"dd-actions", style:"margin-top:4px"}, c.mine
          ? h("button", {class:"dd-btn quiet", type:"button", onclick:act(async () => { if(await ask(tx("delComQ"))){ await be().deleteComment(c.id); refresh(); } })}, tx("del"))
          : h("button", {class:"dd-btn quiet", type:"button", disabled:c.reported, onclick:() => guard(async () => { if(await ask(tx("reportQ"))){ try { await be().report("comment", c.id); say(tx("reported")); refresh(); } catch(e){ say(msg(e)); } } })}, tx(c.reported ? "reported" : "report"))))),
      h("form", {class:"dd-cform", onsubmit:e => { e.preventDefault(); const body = input.value.trim().slice(0, MAX_COMMENT); if(!body) return;
        guard(async () => { try { await be().comment(r.id, body); openComments.add(r.id); refresh(); } catch(x){ say(msg(x)); } }); }},
        input, h("button", {class:"dd-btn", type:"submit"}, tx("send"))));
  }
  return h("article", {class:"dd-card"}, who,
    h("div", {class:"dd-chips"}, h("span", {class:"dd-chip stars", role:"img", "aria-label":tx("stars", {n:r.rating})}, "★".repeat(r.rating) + "☆".repeat(5 - r.rating)), h("span", {class:"dd-chip"}, tx(r.worth ? "worthYes" : "worthNo"))),
    r.hidden ? h("p", {class:"dd-hid"}, tx("hiddenNote")) : null,
    r.body ? h("p", {class:"dd-body"}, r.body) : null,
    r.photos.length ? h("div", {class:"dd-photos"}, r.photos.map((p, i) => h("button", {type:"button", "aria-label":`${tx("photoBy", {n:r.user.nickname})} ${i + 1}`, onclick:() => lightbox(p, r)}, h("img", {class:"cover", src:safeUrl(p.url), alt:"", loading:"lazy"})))) : null,
    h("div", {class:"dd-actions", style:"margin-top:8px"}, actions),
    comments);
}

async function renderFeed(el, rid){
  css(); views.set(el, () => renderFeed(el, rid)); el.classList.add("dd", "dd-feed"); el.setAttribute("aria-busy", "true");
  let list, st;
  try { [list, st] = await Promise.all([be().list(rid), be().stats(rid)]); }
  catch(e){ fill(el,h("p", {class:"dd-alert", role:"alert"}, msg(e))); return; }
  finally { el.removeAttribute("aria-busy"); }
  list.sort((a, b) => (b.photos.length > 0) - (a.photos.length > 0) || b.created - a.created);   // с фото первыми
  const avg = st.avg.toLocaleString(lang() ? "en-GB" : "ru-RU", {minimumFractionDigits:1, maximumFractionDigits:1});
  const shots = list.filter(r => !r.hidden).flatMap(r => r.photos.map(p => [p, r]));
  fill(el,
    h("h3", {}, tx("reviews")),
    h("div", {class:"dd-sum"},
      st.n ? [h("div", {class:"dd-big", role:"img", "aria-label":tx("stars", {n:avg})}, avg, h("small", {"aria-hidden":"true"}, "★")),
              h("div", {}, h("b", {}, tx("worthPct", {n:st.worthPct})), h("div", {class:"dd-meta"}, tx("nReviews", {n:st.n})))]
           : h("p", {class:"dd-note", style:"font-size:15px"}, tx("noReviews")),
      h("button", {class:"dd-btn main", type:"button", "data-dd-review":rid}, tx("cooked"))),
    shots.length ? h("section", {"aria-label":tx("gallery")}, h("p", {class:"dd-label"}, tx("gallery")),
      h("div", {class:"dd-gal"}, shots.map(([p, r], i) => h("button", {type:"button", "aria-label":`${tx("photoBy", {n:r.user.nickname})} ${i + 1}`, onclick:() => lightbox(p, r)}, h("img", {class:"cover", src:safeUrl(p.url), alt:"", loading:"lazy"}))))) : null,
    list.map(r => reviewCard(r, {comments:true})));
}

/* ---------- профиль ---------- */
function favCuisines(cooked){
  const n = {}; for(const c of cooked) if(c.cuisine) n[c.cuisine] = (n[c.cuisine] || 0) + 1;
  return Object.keys(n).sort((a, b) => n[b] - n[a]).slice(0, 3).map(cuLabel);
}
function openEditProfile(p){
  modal(tx("editProfile"), close => {
    const alert = h("p", {class:"dd-alert", role:"alert"});
    let blob = null, preview = null;
    const avaBox = h("div", {class:"dd-who"}, ava(p, true));
    const file = h("input", {type:"file", accept:"image/*", hidden:true, onchange:async () => {
      const f = file.files[0]; file.value = ""; if(!f) return;
      try { blob = await shrink(f, 256); if(preview) URL.revokeObjectURL(preview); preview = URL.createObjectURL(blob); avaBox.replaceChildren(ava({avatar:preview}, true)); } catch(e){ alert.textContent = msg(e); }
    }});
    const name = h("input", {type:"text", maxlength:"60", autocomplete:"name", value:p.name});
    const nick = h("input", {type:"text", maxlength:"24", autocapitalize:"none", spellcheck:"false", value:p.nickname});
    const ig = h("input", {type:"text", maxlength:"60", autocapitalize:"none", spellcheck:"false", value:p.instagram, placeholder:"@username"});
    const submit = h("button", {class:"dd-btn main", type:"submit"}, tx("save"));
    return h("form", {novalidate:true, onsubmit:async e => {
      e.preventDefault(); alert.textContent = "";
      const nk = nick.value.trim().toLowerCase(), handle = ig.value.trim().replace(/^https?:\/\/(www\.)?instagram\.com\//i, "").replace(/^@/, "").replace(/\/.*$/, "");
      if(!NICK_RE.test(nk)){ alert.textContent = tx("nickHint"); nick.focus(); return; }
      if(handle && !IG_RE.test(handle)){ alert.textContent = tx("badIg"); ig.focus(); return; }
      submit.disabled = true;
      try { await be().updateProfile({nickname:nk, name:name.value.trim().slice(0, 60), instagram:handle, avatarBlob:blob, oldAvatar:p.avatarPath}); if(preview) URL.revokeObjectURL(preview); close(); refresh(); }
      catch(x){ alert.textContent = msg(x); }
      finally { submit.disabled = false; }
    }},
      h("div", {class:"dd-field"}, h("span", {class:"dd-label"}, tx("avatar")), h("div", {class:"dd-actions", style:"margin-top:0"}, avaBox, h("button", {class:"dd-btn", type:"button", onclick:() => file.click()}, tx("pickAvatar")), file)),
      field(tx("name"), name), field(tx("nick"), nick, h("p", {class:"dd-note"}, tx("nickHint"))), field(tx("insta"), ig),
      alert, h("div", {class:"dd-actions"}, submit, h("button", {class:"dd-btn quiet", type:"button", onclick:close}, tx("cancel"))));
  });
}
