/* нормализация: неизвестные ключи убираем, штучные позиции округляем */
RECIPES.forEach(r=>{
  for(const k in r.ing){
    if(!ING[k]){ delete r.ing[k]; continue; }
    if(["lemon","lime","apple","avocado"].includes(k)) r.ing[k] = Math.max(1, Math.round(r.ing[k]));
    if(["шт","банка","уп","пучок"].includes(ING[k].u) && r.ing[k] > 6) r.ing[k] = 6;
    if(ING[k].u==="кг" && r.ing[k] > 1.5) r.ing[k] = 1.5;
  }
  if(!r.tags || !r.tags.length) r.tags = ["home"];
  if(!r.gear || !r.gear.length) r.gear = ["stove"];
});

