/* ================= МОСТ К МОДУЛЯМ (работает и без них) ================= */
const RM = () => matchMedia("(prefers-reduced-motion: reduce)").matches;
const FXM = window.FX || {};
/* заголовок проявляется построчно из размытия: слова раскладываются по строкам через offsetTop */
function lineReveal(el, text, opts){
  if(!el) return; opts = opts || {};
  if(text != null) el.textContent = text;
  if(RM() || !el.animate) return;
  const label = el.textContent, parts = [];
  [...el.childNodes].forEach(n=>{
    if(n.nodeType===3) n.textContent.split(/(\s+)/).forEach(w=>{ if(w) parts.push(/^\s+$/.test(w) ? " " : {w}); });
    else parts.push({node:n.cloneNode(true)});
  });
  el.innerHTML = "";
  const spans = [];
  parts.forEach(p=>{
    if(p===" "){ el.appendChild(document.createTextNode(" ")); return; }
    const s = document.createElement("span"); s.style.display = "inline-block"; s.setAttribute("aria-hidden","true");
    if(p.node) s.appendChild(p.node); else s.textContent = p.w;
    el.appendChild(s); spans.push(s);
  });
  el.setAttribute("aria-label", label);
  let line = -1, top = null;
  spans.forEach(s=>{
    const y = s.offsetTop; if(top===null || Math.abs(y-top) > 4){ line++; top = y; }
    s.animate([{opacity:0, filter:"blur(12px)", transform:"translateY(.35em)"},{opacity:1, filter:"blur(0)", transform:"none"}],
      {duration:900, delay:(opts.delay||0) + line*130, easing:"cubic-bezier(.16,1,.3,1)", fill:"backwards"});
  });
}
const F = {
  /* смена экранов без View Transitions: снимок тяжёлой страницы с WebGL давал пустой кадр и лаг.
     Экран меняется сразу, новый слой проявляется только через opacity */
  shutter:  u => Promise.resolve().then(u).then(v=>{ if(!RM()){ const s = document.querySelector(".stage"); s && s.animate([{opacity:.4},{opacity:1}],{duration:220, easing:"linear"}); } return v; }),
  kinetic:  (el,t,o) => lineReveal(el, t, o),
  odometer: (el,t) => { if(!el) return; FXM.odometer ? FXM.odometer(el,t) : (el.textContent = t); },
  confetti: () => {},
  reveal:   (els,o) => FXM.reveal && FXM.reveal(els,o||{}),
  observe:  (r,s) => FXM.observe && FXM.observe(r,s),
  inter:    () => FXM.initInteractions && FXM.initInteractions()
};
/* шрифты кухонь выключены: названия блюд набираются Onest ради читаемости */
const useFont = () => "";

RECIPES.forEach(r=>{ r.nu = window.recipeNutri ? recipeNutri(r) : {k:r.kcal||0,p:0,f:0,c:0,g:0}; r.kcal = r.nu.k; });
const escH = t => String(t).replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));

/* ================= ЯЗЫК: словарь RU / EN =================
   key: [ru, en]. Строка с {var} или функция от объекта vars. */
