  payBack:["К тарифам","Back to pricing"], payH:["Оформление доступа","Get access"], payPlanAria:["Тариф","Plan"],
  payEmailL:["Почта для чека и входа","Email for your receipt and sign-in"], payPromoL:["Промокод, если есть","Promo code, if you have one"], payPromoApply:["Применить","Apply"],
  promoOk:["Промокод принят: первый месяц срока бесплатно","Code accepted: the first month of your term is free"], payTermAria:["Срок","Term"],
  promoBad:["Такого промокода нет или он уже использован","This code doesn't exist or has already been used"],
  promoOff:["скидка {x}","{x} off"],
  payAgree:['Я принимаю <a href="#terms">Пользовательское соглашение</a> и <a href="#offer">Публичную оферту</a> и даю <a href="#privacy">согласие на обработку персональных данных</a>','I accept the <a href="#terms">Terms of Use</a> and the <a href="#offer">Public Offer</a> and consent to the <a href="#privacy">processing of my personal data</a>'],
