function priceIn(key, chain){ const g=ING[key], c=chain||activeChain(), b=REGION.C.base; return (c.p && c.p[key]) || (b && b[key] ? b[key][0] : g.p)*((c.cat&&c.cat[g.cat])||c.idx); }
