  plan.forEach((id,i)=>{ const r=byId(id); if(!r) return;
    for(const k in r.ing) need[k]=(need[k]||0)+r.ing[k]*scale();
    const again = i>0 && plan[i-1]===id, nx = S.useNext && rnext(r);
    if(again && nx && nx.ing) addIng(nx.ing, scale());           // второе блюдо: докупаем только то, что описано в next.ing
    if(!again && S.useSide && r.side) addIng(sideIngs(r), scale()); // гарнир: продукты попадают в корзину
  });
  if(plan===S.plan) for(const k in S.extra||{}) addIng(S.extra[k], scale()); // «Что приготовить из остатков»: докупка по кнопке
