  F.reveal($$("#frGrid .flip"),{step:45});
  $("#frStats").innerHTML = `<div class="kv"><span>${t("frFoods")}</span><b>${S.fridge.length}</b></div><div class="kv"><span>${t("frDishes")}</span><b>${list.length}</b></div><div class="kv"><span>${t("frNoBuy")}</span><b>${list.filter(x=>x.m>=.999).length}</b></div>`;
