$("#pane-set").addEventListener("click", e=>{
  const b = e.target.closest("[data-sp],[data-sd],[data-sdiet],[data-smode]"); if(!b) return;
  const d = b.dataset;
  if(d.smode) S.cookMode = d.smode;
  if(d.sp) S.people = Math.min(30, Math.max(1, S.people + +d.sp));
  if(d.sd) S.days = DAYS.slice(0, Math.min(DAYS.length, Math.max(1, S.days.length + +d.sd)));
  if(d.sdiet) S.diet = d.sdiet;
  save(); renderBasics(); renderHead();
  toast(t("nextBuild"));
});
$("#pane-set").addEventListener("change", e=>{ if(e.target.id==="setBudNum"){ renderBasics(); renderHead(); } });
$("#pane-set").addEventListener("input", e=>{
  if(e.target.id==="setBudNum"){ S.budget = Math.max(REGION.C.budget.step, Math.round(+e.target.value||0)); save(); return; }
  if(e.target.id!=="setBud") return;
  S.budget = +e.target.value; save();
  e.target.style.setProperty("--p", budPct(S.budget)+"%");
  renderBasics(); $("#setBud").focus();
});
