/* ================= ПИТАНИЕ ================= */
const MEALS = [{id:"breakfast",n:"Завтрак",en:{n:"Breakfast"}},{id:"lunch",n:"Обед",en:{n:"Lunch"}},{id:"dinner",n:"Ужин",en:{n:"Dinner"}},{id:"snack",n:"Перекусы",en:{n:"Snacks"}}];
const SPLITS = {balance:{n:"Баланс",en:{n:"Balanced"},p:.25,f:.30,c:.45}, protein:{n:"Больше белка",en:{n:"More protein"},p:.35,f:.25,c:.40}, lowcarb:{n:"Меньше углеводов",en:{n:"Lower carb"},p:.30,f:.40,c:.30}};
const GOALS = {lose:{n:"Похудеть",en:{n:"Lose weight"},k:.85}, keep:{n:"Держать вес",en:{n:"Maintain"},k:1}, gain:{n:"Набрать",en:{n:"Gain weight"},k:1.1}};
const ACTS = [{v:1.2,n:"Сидячий образ",en:{n:"Mostly sitting"}},{v:1.375,n:"Лёгкая активность",en:{n:"Lightly active"}},{v:1.55,n:"Спорт 3-5 раз",en:{n:"Exercise 3-5 times a week"}},{v:1.725,n:"Спорт каждый день",en:{n:"Daily exercise"}},{v:1.9,n:"Тяжёлая работа",en:{n:"Physical job"}}];
function nutriNorm(){
  const P = S.nutri.profile;
  const bmr = 10*P.weight + 6.25*P.height - 5*P.age + (P.sex==="m" ? 5 : -161);
  const tdee = bmr*P.activity, autoK = Math.round(tdee*GOALS[P.goal].k/10)*10, k = S.nutri.kcalGoal || autoK, sp = SPLITS[P.split];
  const autoW = Math.min(14, Math.max(6, Math.round(P.weight*30/250)));
  return {k, autoK, p:Math.round(k*sp.p/4), f:Math.round(k*sp.f/9), c:Math.round(k*sp.c/4), bmr:Math.round(bmr), tdee:Math.round(tdee), water:S.nutri.waterGoal || autoW, autoW};
}
const dkey = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
function ndDate(){ const d = new Date(); d.setDate(d.getDate() + (window.__nd||0)); return d; }
const dayList = key => (S.nutri.diary[key] = S.nutri.diary[key] || []);
const totals = key => (S.nutri.diary[key]||[]).reduce((t,e)=>({k:t.k+e.k, p:t.p+e.p, f:t.f+e.f, c:t.c+e.c}), {k:0,p:0,f:0,c:0});
function mealByHour(){ const h = new Date().getHours(); return h<11 ? "breakfast" : h<16 ? "lunch" : h<21 ? "dinner" : "snack"; }
function addEntry(key, e){ if(!S.nutri.consent) return toastSafe(t("hcAsk")); dayList(key).push({id:Date.now().toString(36)+Math.random().toString(36).slice(2,6), ...e}); save(); }
const fmt1 = v => dec(Math.round(v*10)/10);
/* записи дневника хранят id блюда или продукта, чтобы название переводилось; старые записи показывают сохранённый текст */
const portionTxt = m => m===.5 ? t("half") : `${m} ${pl(m,"portion")}`;
const entryName = e => { const r = e.rid && byId(e.rid); return r ? rn(r) : e.fk && ING[e.fk] ? ingName(e.fk) : e.name; };
const entryAmount = e => e.mult!=null ? portionTxt(e.mult) : e.grams!=null ? `${e.grams} ${t("u_g")}` : e.custom ? t("customEntry") : e.amount;
const dishEntry = (r, m, meal) => ({meal, rid:r.id, name:rn(r), k:r.nu.k*m, p:r.nu.p*m, f:r.nu.f*m, c:r.nu.c*m, mult:m, amount:portionTxt(m)});
const mealName = id => tr(MEALS.find(x=>x.id===id));
function autoDinner(d){
  if(!S.nutri.autoDinner || !S.nutri.consent) return;
  const key = dkey(d);
  if(key!==dkey(new Date()) || S.nutri.autoDone[key]) return;
  const i = S.days.indexOf(DAYS[(d.getDay()+6)%7]); if(i<0 || !S.plan[i]) return;
  const r = byId(S.plan[i]); if(!r) return;
  addEntry(key, {...dishEntry(r, 1, "dinner"), auto:true});
  S.nutri.autoDone[key] = true; save();
}
function kbjuHTML(r){
  if(!r.nu) return "";
  const nu = r.nu, eP = nu.p*4, eF = nu.f*9, eC = nu.c*4, eT = eP+eF+eC || 1, n = nutriNorm();
  return `<div class="kbju glass">
    <div class="kb-row"><div class="kb"><b>${nu.k}</b><span>${t("kcal")}</span></div><div class="kb"><b>${nu.p}</b><span>${t("kb_prot")}</span></div><div class="kb"><b>${nu.f}</b><span>${t("kb_fat")}</span></div><div class="kb"><b>${nu.c}</b><span>${t("kb_carb")}</span></div></div>
    <div class="energy" aria-hidden="true"><i style="flex:${eP};background:var(--mp)"></i><i style="flex:${eF};background:var(--mf)"></i><i style="flex:${eC};background:var(--mc)"></i></div>
    <div class="legend"><span><i style="background:var(--mp)"></i>${t("protein")} ${Math.round(eP/eT*100)}%</span><span><i style="background:var(--mf)"></i>${t("fat")} ${Math.round(eF/eT*100)}%</span><span><i style="background:var(--mc)"></i>${t("carbs")} ${Math.round(eC/eT*100)}%</span></div>
    <div class="src" style="margin-top:8px">${t("kbNote",{g:nu.g, p:Math.round(nu.k/n.k*100)})}</div>
  </div>`;
}
function addBoxHTML(){
  const tab = window.__addTab || "dish";
  const tabs = [["dish","tabDish"],["food","tabFood"],["custom","tabCustom"]].map(([id,k])=>`<button class="chip sm" aria-pressed="${tab===id}" data-addtab="${id}">${t(k)}</button>`).join("");
  const lens = `<svg class="ico" viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/></svg>`;
  let body = "";
  if(tab==="dish") body = `<div class="search-wrap" style="margin-top:10px">${lens}<input class="search" id="ndSearch" placeholder="${t("dishPh")}" autocomplete="off" aria-label="${t("mealSearchAria")}"></div><div class="addres" id="addRes"></div>`;
  if(tab==="food") body = `<div style="display:flex;gap:8px;margin-top:10px"><div class="search-wrap" style="flex:1">${lens}<input class="search" id="nfSearch" placeholder="${t("foodPh")}" autocomplete="off" aria-label="${t("foodAria")}"></div><input class="fld" id="nfGrams" type="number" min="1" value="100" style="width:100px" aria-label="${t("grams")}"></div><div class="addres" id="addRes"></div>`;
  if(tab==="custom") body = `<div class="fields"><input class="fld" id="cuName" placeholder="${t("namePh")}" aria-label="${t("namePh")}"><input class="fld" id="cuK" type="number" min="0" placeholder="${t("kcal")}" aria-label="${t("calories")}"><input class="fld" id="cuP" type="number" min="0" placeholder="${t("pG")}" aria-label="${t("protein")}"><input class="fld" id="cuF" type="number" min="0" placeholder="${t("fG")}" aria-label="${t("fat")}"><input class="fld" id="cuC" type="number" min="0" placeholder="${t("cG")}" aria-label="${t("carbs")}"></div><button class="btn btn-main" style="margin-top:10px;padding:12px 18px" id="addCustom">${t("log")}</button>`;
  return `<div class="addbox"><div class="chips-row">${tabs}</div>${body}</div>`;
}
function renderAddResults(){
  const box = $("#addRes"); if(!box) return;
  const tab = window.__addTab || "dish";
  if(tab==="dish"){
    const q = (($("#ndSearch")||{}).value||"").toLowerCase().trim();
    const list = RECIPES.filter(r=>dietOk(r) && (!q || hit(q, rn(r), r.n))).slice(0, q?14:6);
    box.innerHTML = list.map(r=>`<div class="addrow"><div style="min-width:0"><b>${rn(r)}</b><div class="src">${t("perServingMacro",{k:r.nu.k, p:r.nu.p, f:r.nu.f, c:r.nu.c})}</div></div><div class="chips-row" style="margin:0">${[.5,1,2].map(m=>`<button class="chip sm" data-adddish="${r.id}" data-mult="${m}" aria-label="${portionTxt(m)}">${m===.5?"½":m}</button>`).join("")}</div></div>`).join("") || `<div class="src">${t("nothingFound")}</div>`;
  }
  if(tab==="food"){
    const q = (($("#nfSearch")||{}).value||"").toLowerCase().trim(), g = Math.max(1, +(($("#nfGrams")||{}).value||100)), ex = excludedKeys();
    const keys = Object.keys(ING).filter(k=>window.NUTRI && NUTRI[k] && NUTRI[k][0]>0 && (!q || hit(q, ingName(k), ING[k].n))).slice(0, q?14:6);
    box.innerHTML = keys.map(k=>{ const nu = foodNutri(k,g); return `<div class="addrow"><div style="min-width:0"><b>${ingName(k)}${ex.has(k)?`<span class="est">${t("youSkip",{x:""}).replace(/:\s*$/,"")}</span>`:""}</b><div class="src">${t("gramsMacro",{g, k:nu.k, p:fmt1(nu.p), f:fmt1(nu.f), c:fmt1(nu.c)})}</div></div><button class="chip sm" data-addfood="${k}" aria-label="${escH(t("addX",{x:ingName(k)}))}">+</button></div>`; }).join("") || `<div class="src">${t("nothingFound")}</div>`;
  }
}
function suggestBlock(key){
  const n = nutriNorm(), tt = totals(key), rem = {k:n.k-tt.k, p:n.p-tt.p, f:n.f-tt.f, c:n.c-tt.c};
  if(rem.k < 150) return {sub:t("almostDone"), html:`<p class="src">${t("leftSnack",{k:Math.max(0,Math.round(rem.k))})}</p>`};
  const list = RECIPES.filter(r=>dietOk(r) && r.nu.k <= rem.k*1.08).map(r=>({r, s:
    1 - Math.abs(r.nu.k - rem.k*.85)/rem.k + (rem.p>0 ? Math.min(r.nu.p,rem.p)/rem.p : 0)*.8 - (rem.f>0 ? Math.max(0,r.nu.f-rem.f)/rem.f : 1)*.6 + (hasPhoto(r)?.08:0)
  })).sort((a,b)=>b.s-a.s).slice(0,4);
  return {sub:t("leftSub",{k:Math.round(rem.k), p:Math.max(0,Math.round(rem.p)), f:Math.max(0,Math.round(rem.f)), c:Math.max(0,Math.round(rem.c))}),
    html: list.map(({r})=>`<div class="addrow" style="grid-template-columns:54px minmax(0,1fr) auto;margin-top:6px"><span class="thumb" style="width:54px;height:54px;border-radius:14px">${dishArt(r)}</span><button style="min-width:0" data-open="${r.id}" data-cursor="${t("curRecipe")}"><b>${rn(r)}</b><div class="src">${t("macroLine",{k:r.nu.k, p:r.nu.p, f:r.nu.f, c:r.nu.c})}</div></button><button class="chip sm" data-suggestadd="${r.id}">${t("toDiary")}</button></div>`).join("") || `<p class="src">${t("nothingFits")}</p>`};
}
function weekChart(){
  const W=440, H=220, L=44, R=12, T=22, B=34, n = nutriNorm(), end = ndDate();
  const days = [...Array(7)].map((_,i)=>{ const d = new Date(end); d.setDate(d.getDate()-6+i); const k = dkey(d); return {d, k, t:totals(k)}; });
  const max = Math.max(n.k*1.25, ...days.map(x=>x.t.k)) || 1;
  const y = v => T + (H-T-B)*(1 - v/max), bw = (W-L-R)/7, barW = Math.min(48, bw*.56);
  let grid = "";
  [0, .5, 1].forEach(fr=>{ const v = Math.round(max*fr/100)*100; grid += `<line x1="${L}" x2="${W-R}" y1="${y(v).toFixed(1)}" y2="${y(v).toFixed(1)}" style="stroke:rgba(255,255,255,.07)"/><text x="${L-8}" y="${(y(v)+4).toFixed(1)}" text-anchor="end" font-size="12" style="fill:var(--ink3)">${v}</text>`; });
  const bars = days.map((x,i)=>{
    const cx = L + bw*i + bw/2, x0 = cx - barW/2, top = y(x.t.k), base = y(0), h = base-top, r = Math.min(4, h);
    const path = h>0.5 ? `M${x0.toFixed(1)},${base.toFixed(1)} V${(top+r).toFixed(1)} Q${x0.toFixed(1)},${top.toFixed(1)} ${(x0+r).toFixed(1)},${top.toFixed(1)} H${(x0+barW-r).toFixed(1)} Q${(x0+barW).toFixed(1)},${top.toFixed(1)} ${(x0+barW).toFixed(1)},${(top+r).toFixed(1)} V${base.toFixed(1)} Z` : "";
    const sel = i===6;
    return `<path d="${path}" style="fill:var(--a1);opacity:${sel?1:.5}"/><text x="${cx.toFixed(1)}" y="${H-12}" text-anchor="middle" font-size="12.5" font-weight="${sel?800:600}" style="fill:${sel?"var(--ink)":"var(--ink3)"}">${dshort((x.d.getDay()+6)%7)}</text><rect x="${(L+bw*i).toFixed(1)}" y="${T}" width="${bw.toFixed(1)}" height="${H-T-B}" style="fill:transparent" data-wk="${i}"/>`;
  }).join("");
  const gy = y(n.k);
  const goal = `<line x1="${L}" x2="${W-R}" y1="${gy.toFixed(1)}" y2="${gy.toFixed(1)}" style="stroke:var(--a3)" stroke-width="1.5" stroke-dasharray="5 5"/><text x="${W-R}" y="${(gy-7).toFixed(1)}" text-anchor="end" font-size="12" font-weight="700" style="fill:var(--ink2)">${t("normX",{k:n.k})}</text>`;
  window.__weekDays = days.map((x,i)=>({...x, cx:L+bw*i+bw/2, top:y(x.t.k), W}));
  const avg = Math.round(days.reduce((s,x)=>s+x.t.k,0) / Math.max(1, days.filter(x=>x.t.k>0).length));
  return {sub: days.some(x=>x.t.k>0) ? t("avgKcal",{a:avg, k:n.k}) : t("noWeekEntries"),
    html:`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${t("weekAria")}">${grid}${goal}${bars}</svg><div class="tip" id="weekTip"></div>`};
}
function weightChart(){
  const pts = [...S.nutri.weights].sort((a,b)=>a.d<b.d?-1:1).slice(-30), P = S.nutri.profile;
  if(pts.length<2) return {html:`<p class="src" style="margin-top:10px">${t("twoWeights")}</p>`};
  const W=440, H=210, L=44, R=12, T=20, B=30;
  const vals = pts.map(p=>p.kg).concat(P.target ? [P.target] : []);
  let mn = Math.min(...vals), mx = Math.max(...vals); if(mx-mn<2){ mx += 1; mn -= 1; }
  const pad = (mx-mn)*.12; mn -= pad; mx += pad;
  const x = i => L + (W-L-R)*(i/(pts.length-1)), y = v => T + (H-T-B)*(1-(v-mn)/(mx-mn));
  const line = pts.map((p,i)=>`${i?"L":"M"}${x(i).toFixed(1)},${y(p.kg).toFixed(1)}`).join(" ");
  const area = `${line} L${x(pts.length-1).toFixed(1)},${H-B} L${x(0).toFixed(1)},${H-B} Z`;
  let grid = "";
  [0, .5, 1].forEach(fr=>{ const v = mn + (mx-mn)*fr; grid += `<line x1="${L}" x2="${W-R}" y1="${y(v).toFixed(1)}" y2="${y(v).toFixed(1)}" style="stroke:rgba(255,255,255,.07)"/><text x="${L-8}" y="${(y(v)+4).toFixed(1)}" text-anchor="end" font-size="12" style="fill:var(--ink3)">${fmt1(v)}</text>`; });
  const dd = s => s.slice(8,10)+"."+s.slice(5,7);
  grid += `<text x="${L}" y="${H-8}" font-size="12" style="fill:var(--ink3)">${dd(pts[0].d)}</text><text x="${W-R}" y="${H-8}" text-anchor="end" font-size="12" style="fill:var(--ink3)">${dd(pts[pts.length-1].d)}</text>`;
  const targ = P.target ? `<line x1="${L}" x2="${W-R}" y1="${y(P.target).toFixed(1)}" y2="${y(P.target).toFixed(1)}" style="stroke:var(--a3)" stroke-width="1.5" stroke-dasharray="5 5"/><text x="${W-R}" y="${(y(P.target)-7).toFixed(1)}" text-anchor="end" font-size="12" font-weight="700" style="fill:var(--ink2)">${t("goalKg",{x:fmt1(P.target)})}</text>` : "";
  const last = pts.length-1;
  window.__wGeom = {pts, xs:pts.map((_,i)=>x(i)), ys:pts.map(p=>y(p.kg)), W, L, R};
  return {html:`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${t("weightAria")}">
    <defs><linearGradient id="wfill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" style="stop-color:var(--a2);stop-opacity:.28"/><stop offset="1" style="stop-color:var(--a2);stop-opacity:0"/></linearGradient></defs>
    ${grid}${targ}<path d="${area}" style="fill:url(#wfill)"/><path d="${line}" style="fill:none;stroke:var(--a2)" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>
    <line id="wCross" x1="0" x2="0" y1="${T}" y2="${H-B}" style="stroke:rgba(255,255,255,.28);opacity:0"/>
    <circle cx="${x(last).toFixed(1)}" cy="${y(pts[last].kg).toFixed(1)}" r="5" style="fill:var(--a2);stroke:var(--bg0)" stroke-width="2"/>
    <circle id="wDot" r="5" style="fill:var(--a2);stroke:var(--bg0);opacity:0" stroke-width="2"/>
    <rect x="${L}" y="${T}" width="${W-L-R}" height="${H-T-B}" style="fill:transparent" id="wHit"/></svg><div class="tip" id="wTip"></div>`};
}
function profileHTML(){
  const P = S.nutri.profile, n = nutriNorm();
  const chipsRow = (items, key, cur) => `<div class="chips-row">${items.map(([v,tx])=>`<button class="chip sm" aria-pressed="${String(cur)===String(v)}" data-${key}="${v}">${tx}</button>`).join("")}</div>`;
  return `<div class="chips-row" style="margin-top:12px">${[["m","male"],["f","female"]].map(([v,k])=>`<button class="chip sm" aria-pressed="${P.sex===v}" data-psex="${v}">${t(k)}</button>`).join("")}</div>
    <div class="prof">${[["age","age",P.age],["height","heightCm",P.height],["weight","weightKg",P.weight],["target","goalKgL",P.target]].map(([k,lk,v])=>`<label>${t(lk)}<input class="fld" type="number" data-pnum="${k}" value="${v}"></label>`).join("")}</div>
    <div class="sub" style="margin-top:14px">${t("activity")}</div>${chipsRow(ACTS.map(a=>[a.v,tr(a)]), "pact", P.activity)}
    <div class="sub" style="margin-top:12px">${t("goal")}</div>${chipsRow(Object.entries(GOALS).map(([id,g])=>[id,tr(g)]), "pgoal", P.goal)}
    <div class="sub" style="margin-top:12px">${t("macroSplit")}</div>${chipsRow(Object.entries(SPLITS).map(([id,sp])=>[id,`${tr(sp)} ${Math.round(sp.p*100)}/${Math.round(sp.f*100)}/${Math.round(sp.c*100)}`]), "psplit", P.split)}
    <div style="margin-top:10px"><div class="kv"><span>${t("bmr")}</span><b>${t("kcalN",{n:n.bmr})}</b></div><div class="kv"><span>${t("tdee")}</span><b>${t("kcalN",{n:n.tdee})}</b></div><div class="kv"><span>${t("goalNorm")}</span><b>${t("kcalN",{n:n.k})}</b></div></div>
    <div class="rule"><div class="t"><b>${t("autoDinnerT")}</b><p>${t("autoDinnerD")}</p></div><button class="sw" id="autoDinnerSw" aria-pressed="${!!S.nutri.autoDinner}" aria-label="${t("autoDinnerT")}"></button></div>`;
}
const LOCK_SVG = '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="11" width="14" height="10" rx="2.5"/><path d="M8 11V8a4 4 0 0 1 8 0v3"/></svg>';
function nutriLockHTML(){
  const act = S.trial && !hasAccess() ? `<button class="btn btn-main" type="button" data-trialnow>${t("trialWaitsBtn")}</button>`
    : REGION.pay ? `<button class="btn btn-main" type="button" data-upgrade="pro">${t("nlBtn")}</button>`
    : `<a class="btn btn-ghost" href="#pricing">${t("soonPay")}</a>`;
  return `<div class="glass panel hc-gate nd-lock">
    <span class="s-ico" style="--c:var(--violet)" aria-hidden="true">${LOCK_SVG}</span>
    <h3>${t("nlT")}</h3><p class="src" style="margin-top:8px;max-width:62ch">${t("nlP")}</p>
    <div class="nd-lock-acts">${act}</div>
  </div>`;
}
document.addEventListener("click", e=>{ const b = e.target.closest("[data-upgrade]"); if(b) openPay(b.dataset.upgrade, +b.dataset.months || 12); });
/* отдельное согласие на данные о здоровье: без него дневник скрыт и ничего не пишет */
function gateHTML(){
  return `<div class="glass panel hc-gate">
    <span class="s-ico" style="--c:var(--mint)" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 3l7 3v5c0 4.5-3 8.3-7 10-4-1.7-7-5.5-7-10V6z"/><path d="M9 12l2 2 4-4"/></svg></span>
    <h3>${t("hcT")}</h3><p class="src" style="margin-top:8px;max-width:62ch">${t("hcP")}</p>
    <div class="p-consent" id="hcBox"><input type="checkbox" id="hcAgree" aria-describedby="hcErr"><label for="hcAgree">${t("hcAgree")}</label></div>
    <p class="p-err" id="hcErr" role="alert" hidden></p>
    <button class="btn btn-main" type="button" id="hcGo" style="margin-top:16px">${t("hcGo")}</button>
  </div>`;
}
const hourSel = (k, v, label) => `<select class="fld sel" data-rm="${k}" aria-label="${escH(label)}">${[...Array(24)].map((_,i)=>`<option value="${i}"${i===v?" selected":""}>${String(i).padStart(2,"0")}:00</option>`).join("")}</select>`;
function remindHTML(){
  const R = S.nutri.remind, n = nutriNorm(), perm = "Notification" in window ? Notification.permission : "unsupported";
  return `<div class="rule" style="margin-top:6px"><div class="t"><b>${t("rmOn")}</b></div><button class="sw" id="rmSw" aria-pressed="${!!R.on}" aria-label="${t("rmOn")}"></button></div>
    <div class="rm-grid${R.on?"":" off"}">
      <div class="sub" id="rmE">${t("rmEvery")}</div>
      <div class="chips-row" role="group" aria-labelledby="rmE">${[30,60,90,120].map(m=>`<button class="chip sm" aria-pressed="${R.every===m}" data-rmevery="${m}">${t("rmMin",{n:m})}</button>`).join("")}</div>
      <div class="rm-row"><span class="sub">${t("rmHours")}</span><span class="rm-pair">${t("rmFrom")} ${hourSel("from",R.from,t("rmHours")+", "+t("rmFrom"))} ${t("rmTo")} ${hourSel("to",R.to,t("rmHours")+", "+t("rmTo"))}</span></div>
      <div class="rm-row"><span class="sub">${t("rmQuiet")}</span><span class="rm-pair">${t("rmFrom")} ${hourSel("qFrom",R.qFrom,t("rmQuiet")+", "+t("rmFrom"))} ${t("rmTo")} ${hourSel("qTo",R.qTo,t("rmQuiet")+", "+t("rmTo"))}</span></div>
      ${perm==="granted" ? `<p class="src" style="color:var(--mint)">${t("rmNotifOn")}</p>` : perm==="denied" ? `<p class="src">${t("rmNotifOff")}</p>` : perm==="default" ? `<button class="btn btn-ghost btn-sm" type="button" id="rmNotif">${t("rmNotif")}</button>` : ""}
    </div>
    <div class="rm-nums">
      <label>${t("rmKcal")}<input class="fld" type="number" inputmode="numeric" min="800" max="6000" step="50" data-rmnum="kcalGoal" value="${S.nutri.kcalGoal||""}" placeholder="${t("rmAuto",{n:n.autoK})}"></label>
      <label>${t("rmWater")}<input class="fld" type="number" inputmode="numeric" min="1" max="20" data-rmnum="waterGoal" value="${S.nutri.waterGoal||""}" placeholder="${t("rmAuto",{n:n.autoW})}"></label>
    </div>
    <p class="src" style="margin-top:12px">${t("rmHonest")}</p>
    <button class="linkbtn" type="button" id="hcWithdraw" style="margin-top:10px">${t("hcWithdraw")}</button>`;
}
function renderNutri(){
  if(!$("#pane-nutri")) return;
  $$('#dock [data-tab="nutri"] .dk-lock').forEach(i=>{ i.hidden = canNutriNow(); });
  /* «Питание» только Pro Plus и пробный месяц: вкладка видна, но с замком и объяснением */
  if(!canNutriNow()){ $("#ndCols").hidden = true; $("#ndGate").innerHTML = nutriLockHTML(); return; }
  const consent = !!S.nutri.consent;
  $("#ndCols").hidden = !consent; $("#ndGate").innerHTML = consent ? "" : gateHTML();
  if(!consent) return;
  const d = ndDate(), key = dkey(d), n = nutriNorm();
  autoDinner(d);
  const tt = totals(key), off = window.__nd||0, left = n.k - tt.k;
  $("#ndDate").textContent = off===0 ? t("today") : off===-1 ? t("yesterday") : off===1 ? t("tomorrow") : d.toLocaleDateString(loc(),{day:"numeric", month:"long"});
  $("#ndSub").textContent = t("normSub",{k:n.k, p:n.p, f:n.f, c:n.c});
  $("#kRing").classList.toggle("over", left<0);
  requestAnimationFrame(()=>ringTo($("#kFg"), tt.k/n.k, 452.4));
  F.odometer($("#kLeft"), String(Math.abs(Math.round(left))));
  $("#kLeftCap").textContent = left>=0 ? t("kcalLeft") : t("kcalOver");
  $("#macroBars").innerHTML = `<div class="mbar"><div class="t"><b>${t("eaten")}</b><span class="num">${Math.round(tt.k)} / ${n.k} ${t("kcal")}</span></div></div>` +
    [["protein","p",n.p,"--mp"],["fat","f",n.f,"--mf"],["carbs","c",n.c,"--mc"]].map(([nm,k,goal,cv])=>
      `<div class="mbar"><div class="t"><b>${t(nm)}</b><span class="num">${Math.round(tt[k])} / ${goal} ${t("u_g")}${tt[k]>goal?` · ${t("overNorm")}`:""}</span></div><div class="tr"><i style="width:${Math.min(100,tt[k]/goal*100).toFixed(1)}%;background:var(${cv})"></i></div></div>`).join("");
  const list = dayList(key);
  $("#meals").innerHTML = MEALS.map(m=>{
    const es = list.filter(e=>e.meal===m.id), mk = Math.round(es.reduce((s,e)=>s+e.k,0)), open = window.__addMeal===m.id;
    return `<div class="meal glass"><div class="meal-head"><div><h4>${tr(m)}</h4><span class="src">${t("mealKcal",{k:mk, n:es.length})}</span></div><button class="btn ${open?"btn-main":"btn-ghost"}" style="padding:10px 16px" data-addmeal="${m.id}">${open?t("done"):t("add")}</button></div>
      ${es.map(e=>`<div class="entry"><div style="min-width:0"><div class="nm">${escH(entryName(e))}${e.auto?`<span class="auto">${t("fromPlan")}</span>`:""}</div><div class="sm">${t("entryMacro",{a:escH(entryAmount(e)), p:fmt1(e.p), f:fmt1(e.f), c:fmt1(e.c)})}</div></div><b class="num">${Math.round(e.k)} ${t("kcal")}</b><button class="mini" data-delentry="${e.id}" aria-label="${t("delEntry")}">${ICON.x}</button></div>`).join("")}
      ${open ? addBoxHTML() : ""}</div>`;
  }).join("");
  renderAddResults();
  const sg = suggestBlock(key); $("#sugSub").textContent = sg.sub; $("#sugList").innerHTML = sg.html;
  const wk = weekChart(); $("#weekSub").textContent = wk.sub; $("#weekChart").innerHTML = wk.html;
  const cups = S.nutri.water[key]||0;
  $("#waterSub").textContent = t("waterSub",{a:cups, b:n.water, l:fmt1(cups*.25)});
  $("#water").innerHTML = [...Array(n.water)].map((_,i)=>`<button class="glassw${i<cups?" on":""}" data-water="${i+1}" aria-label="${t("glassesN",{n:i+1})}"><i></i></button>`).join("");
  const ws = [...S.nutri.weights].sort((a,b)=>a.d<b.d?-1:1), P = S.nutri.profile;
  if(ws.length){ const lw = ws[ws.length-1].kg, diff = lw-ws[0].kg;
    $("#wSub").textContent = t("wNow",{x:fmt1(lw)}) + (ws.length>1 ? t("wDelta",{down:diff<=0, x:fmt1(Math.abs(diff)), d:`${ws[0].d.slice(8,10)}.${ws[0].d.slice(5,7)}`}) : "") + (P.target ? t("wToGoal",{x:fmt1(Math.abs(lw-P.target))}) : "");
  } else $("#wSub").textContent = t("wHint");
  $("#wChart").innerHTML = weightChart().html;
  $("#profile").innerHTML = profileHTML();
  $("#remindBox").innerHTML = remindHTML();
}
function chartTip(container, tip, xSvg, ySvg, W, html){
  const svg = container.querySelector("svg"), rc = svg.getBoundingClientRect(), k = rc.width / W;
  tip.innerHTML = html; tip.style.left = (xSvg*k)+"px"; tip.style.top = (ySvg*k)+"px"; tip.classList.add("on");
}
document.addEventListener("pointermove", e=>{
  const wc = e.target.closest("#weekChart");
  if(wc){ const r = e.target.closest("[data-wk]"), tip = $("#weekTip");
    if(r && window.__weekDays){ const x = window.__weekDays[+r.dataset.wk]; chartTip(wc, tip, x.cx, Math.min(x.top, 200), x.W, `${t("tipKcal",{d:x.d.toLocaleDateString(loc(),{weekday:"short", day:"numeric", month:"short"}), k:Math.round(x.t.k)})}<br><span class="src">${t("tipMacro",{p:Math.round(x.t.p), f:Math.round(x.t.f), c:Math.round(x.t.c)})}</span>`); }
    else if(tip) tip.classList.remove("on");
  } else { const tip = $("#weekTip"); if(tip) tip.classList.remove("on"); }
  const wch = e.target.closest("#wChart"), g = window.__wGeom;
  if(wch && g && e.target.id==="wHit"){
    const svg = wch.querySelector("svg"), rc = svg.getBoundingClientRect(), px = (e.clientX-rc.left)/rc.width*g.W;
    let i = 0, best = 1e9; g.xs.forEach((xx,j)=>{ const dd = Math.abs(xx-px); if(dd<best){ best = dd; i = j; } });
    const cr = $("#wCross"), dot = $("#wDot");
    cr.setAttribute("x1", g.xs[i]); cr.setAttribute("x2", g.xs[i]); cr.style.opacity = 1;
    dot.setAttribute("cx", g.xs[i]); dot.setAttribute("cy", g.ys[i]); dot.style.opacity = 1;
    chartTip(wch, $("#wTip"), g.xs[i], g.ys[i]-8, g.W, `${g.pts[i].d.slice(8,10)}.${g.pts[i].d.slice(5,7)}: ${t("kgV",{x:fmt1(g.pts[i].kg)})}`);
  } else if($("#wTip")){ $("#wTip").classList.remove("on"); const cr = $("#wCross"), dot = $("#wDot"); if(cr) cr.style.opacity = 0; if(dot) dot.style.opacity = 0; }
}, {passive:true});
function nutriClick(b, e){
  const d = b.dataset, key = dkey(ndDate());
  if(b.id==="hcGo"){
    const box = $("#hcBox"); box.classList.remove("bad");
    if(!$("#hcAgree").checked){ $("#hcErr").textContent = t("hcNeed"); $("#hcErr").hidden = false; void box.offsetWidth; box.classList.add("bad"); $("#hcAgree").focus(); return true; }
    S.nutri.consent = {v:DD_LEGAL.version, at:new Date().toISOString()}; save(); renderNutri(); return true;
  }
  if(b.id==="hcWithdraw"){
    Object.assign(S.nutri, {consent:null, diary:{}, water:{}, weights:[], autoDone:{}}); S.nutri.remind.on = false; save(); renderNutri(); toast(t("hcWithdrawn")); return true;
  }
  if(b.id==="rmSw"){ S.nutri.remind.on = !S.nutri.remind.on; S.nutri.remind.last = Date.now(); save(); renderNutri(); $("#rmSw").focus(); return true; }
  if(d.rmevery){ S.nutri.remind.every = +d.rmevery; save(); renderNutri(); return true; }
  if(b.id==="rmNotif"){ if("Notification" in window) Notification.requestPermission().then(()=>renderNutri()); return true; }
  if(d.ndate){ window.__nd = +d.ndate===0 ? 0 : (window.__nd||0) + (+d.ndate); window.__addMeal = null; renderNutri(); return true; }
  if(d.addmeal){ window.__addMeal = window.__addMeal===d.addmeal ? null : d.addmeal; renderNutri(); const inp = $("#ndSearch")||$("#nfSearch"); if(inp) inp.focus(); return true; }
  if(d.addtab){ window.__addTab = d.addtab; renderNutri(); return true; }
  if(d.adddish){ const r = byId(d.adddish), m = +d.mult; addEntry(key, dishEntry(r, m, window.__addMeal||mealByHour())); renderNutri(); toast(t("logged",{x:rn(r)})); return true; }
  if(d.addfood){ const g = Math.max(1, +(($("#nfGrams")||{}).value||100)), nu = foodNutri(d.addfood, g); addEntry(key, {meal:window.__addMeal||mealByHour(), fk:d.addfood, name:ingName(d.addfood), ...nu, grams:g, amount:`${g} ${t("u_g")}`}); renderNutri(); toast(t("logged",{x:ingName(d.addfood)})); return true; }
  if(b.id==="addCustom"){ const name = ($("#cuName").value||"").trim(), k = +$("#cuK").value;
    if(!name || !(k>=0) || $("#cuK").value===""){ toast(t("enterNameKcal")); return true; }
    addEntry(key, {meal:window.__addMeal||mealByHour(), name, k, p:+$("#cuP").value||0, f:+$("#cuF").value||0, c:+$("#cuC").value||0, custom:true, amount:t("customEntry")}); renderNutri(); toast(t("loggedShort")); return true; }
  if(d.delentry){ S.nutri.diary[key] = dayList(key).filter(x=>x.id!==d.delentry); save(); renderNutri(); return true; }
  if(d.water){ const v = +d.water, cur = S.nutri.water[key]||0; S.nutri.water[key] = cur===v ? v-1 : v; save(); renderNutri(); if(S.nutri.water[key]===nutriNorm().water){ const r = b.getBoundingClientRect(); F.confetti(r.left+17, r.top+20, {count:70, spread:.7}); toast(t("waterDone")); } return true; }
  if(b.id==="saveWeight"){ const kg = parseFloat(String($("#wInput").value).replace(",", "."));
    if(!(kg>=30 && kg<=300)){ toast(t("weightRange")); return true; }
    const today = dkey(new Date()); S.nutri.weights = S.nutri.weights.filter(w=>w.d!==today).concat({d:today, kg}); S.nutri.profile.weight = kg; save(); renderNutri(); toast(t("weightLogged",{x:fmt1(kg)})); return true; }
  if(d.psex){ S.nutri.profile.sex = d.psex; save(); renderNutri(); return true; }
  if(d.pact){ S.nutri.profile.activity = +d.pact; save(); renderNutri(); return true; }
  if(d.pgoal){ S.nutri.profile.goal = d.pgoal; save(); renderNutri(); return true; }
  if(d.psplit){ S.nutri.profile.split = d.psplit; save(); renderNutri(); return true; }
  if(b.id==="autoDinnerSw"){ S.nutri.autoDinner = !S.nutri.autoDinner; save(); renderNutri(); return true; }
  if(d.suggestadd){ const r = byId(d.suggestadd), m = mealByHour(); addEntry(key, dishEntry(r, 1, m)); renderNutri(); toast(t("loggedMeal",{m:mealName(m).toLowerCase()})); return true; }
  return false;
}

/* ================= ТЕМА: системная / светлая / тёмная (S.theme), по умолчанию системная ================= */
const THEME_MQ = matchMedia("(prefers-color-scheme: light)");
function applyTheme(){
  const pick = S.theme || "system", mode = pick==="system" ? (THEME_MQ.matches ? "light" : "dark") : pick;
  document.documentElement.dataset.theme = mode;
  const m = document.querySelector('meta[name="theme-color"]'); if(m) m.content = mode==="light" ? "#F4F6FB" : "#05070F";
  $$("[data-theme-set]").forEach(b=>b.setAttribute("aria-checked", String(b.dataset.themeSet===pick)));
}
if(THEME_MQ.addEventListener) THEME_MQ.addEventListener("change", ()=>{ if((S.theme||"system")==="system") applyTheme(); });
document.addEventListener("click", e=>{ const b = e.target.closest("[data-theme-set]"); if(!b) return; S.theme = b.dataset.themeSet; save(); applyTheme(); });

/* ================= ОСТАТКИ: три разных блюда =================
   Данные: window.NEXT3_PATCH[id] (src/overlay/next3_*.js) или r.next3 = [{n, en_n, type, t, how, en_how, ing}].
   Нет данных - старый r.next одним вариантом, так и пишем. Докупка - S.extra[id:i] = ing, её считает basket() */
function next3(r){
  const p = (window.NEXT3_PATCH||{})[r.id] || r.next3;
  if(Array.isArray(p) && p.length) return p.slice(0,3);
  const n = rnext(r);
  return n ? [{n:n.n, type:"left", t:n.t, how:n.how||[], ing:n.ing||{}}] : [];
}
const n3n = o => S.lang==="en" && o.en_n ? o.en_n : o.n;
const n3how = o => S.lang==="en" && o.en_how && o.en_how.length ? o.en_how : (o.how||[]);
const L3_TYPES = ["soup","salad","bake","filling","bowl","pan"], L3_COLORS = ["--c1:#6EE7F9;--c2:#8B7CF6","--c1:#F0A8D0;--c2:#FFC857","--c1:#5EE3A1;--c2:#6EE7F9"];
function leftHTML(r){
  const L = next3(r);
  return `<span class="grab" aria-hidden="true"></span><button class="icon-btn close" data-close aria-label="${t("close")}">${ICON.x}</button>
    <div class="in"><button type="button" class="btn btn-ghost btn-sm" data-openrec="${r.id}">${t("left3Back")}</button>
      <h2 id="winTitle">${escH(t("left3H",{x:rn(r)}))}</h2><p class="src" style="margin-top:6px">${t(L.length > 1 ? "left3P" : "left3One")}</p>
      <div class="l3-list">${L.map((o,i)=>{
        const key = r.id + ":" + i, on = !!(S.extra||{})[key], ings = Object.keys(o.ing||{}).filter(k=>ING[k]);
        return `<article class="l3 glass">
          <div class="l3-art art" style="${L3_COLORS[i%3]}" role="img" aria-label="${escH(n3n(o))}"><span class="l3-type">${t("lt_" + (L3_TYPES.includes(o.type) ? o.type : "left"))}</span></div>
          <div class="l3-in"><h3>${escH(n3n(o))}</h3>${+o.t ? `<div class="meta"><span>${+o.t} ${t("min")}</span></div>` : ""}
            <ol class="steps-mini">${n3how(o).slice(0,4).map((s,j)=>`<li><b>${j+1}</b><span>${escH(s)}</span></li>`).join("")}</ol>
            ${ings.length ? `<div class="ing-chips">${ings.map(k=>`<span>${ingName(k)}</span>`).join("")}</div><button type="button" class="btn ${on ? "btn-ghost" : "btn-main"} btn-sm" data-leftbuy="${key}" aria-pressed="${on}">${t(on ? "left3Bought" : "left3Buy")}</button>` : `<p class="src">${t("left3Nothing")}</p>`}
          </div></article>`; }).join("")}</div></div>`;
}

/* ================= РЕЦЕПТ ================= */
let sheetSrc = null, sheetId = null, sheetMode = "";
function recipeHTML(r){
  const bad = badIngs(r), how = rhow(r), nxt = rnext(r), alt = ralt(r), side = rside(r), tip = rtip(r);
  const rows = Object.keys(r.ing).map(k=>{ const q=r.ing[k]*scale(), g=ING[k]; return `<div class="ing-row${S.fridge.includes(k)?" have":""}${bad.includes(k)?" bad":""}"><span>${ingName(k)}${REGION.cc==="BY"&&g.sale?` <span class="sale">-${g.sale}%</span>`:""}</span><span class="g">${qty(q,g.u)}</span><span class="c">${rub(q*priceIn(k))}</span></div>`; }).join("");
  return `<span class="grab" aria-hidden="true"></span><div class="hero-img">${dishArt(r)}</div><button class="icon-btn close" data-close aria-label="${t("close")}">${ICON.x}</button>
    <div class="in"><div class="hello">${cuName(r.cu)}</div><h2 id="winTitle" style="${useFont(r.cu)}">${rn(r)}</h2>
      <div class="facts"><div class="fact">${t("f_time")}<b>${r.t} ${t("min")}</b></div><div class="fact">${t("f_servings")}<b>${S.people}</b></div><div class="fact">${t("f_serving")}<b>${rub(perPortion(r))}</b></div></div>
      ${kbjuHTML(r)}
      ${bad.length?`<div class="warnbox">${t("containsSkip",{x:bad.map(ingName).join(", ")})}</div>`:""}
      <div class="act-row" style="display:flex;gap:10px;margin-top:18px;flex-wrap:wrap"><button class="btn btn-main" data-cook="${r.id}" data-magnet>${t("cookStepsN",{n:how.length})}</button><button class="btn btn-ghost" data-dd-review="${r.id}">${t("cookedBtn")}</button><button class="btn btn-ghost" data-todiary="${r.id}">${t("toDiary")}</button>${S.plan.includes(r.id)?"":`<button class="btn btn-ghost" data-add="${r.id}">${t("addToWeek")}</button>`}</div>
      <div id="ddFeed" class="win-feed"></div>
      <div class="sec glass open"><button class="sec-head" data-sec>${t("ingredientsN",{n:Object.keys(r.ing).length})} ${ICON.chev}</button><div class="acc"><div><div style="padding:0 18px 12px">${rows}</div></div></div></div>
      ${side?`<div class="tip"><b>${t("serveWith")}</b><span>${side}</span></div>`:""}
      ${next3(r).length ? `<button type="button" class="btn btn-ghost l3-open" data-left3="${r.id}">${t("left3Btn")}</button>${r.keep ? `<p class="src" style="margin:8px 0 0">${t("keepsDays",{n:r.keep})}</p>` : ""}` : ""}
      ${alt && Object.keys(alt).length?`<div class="sec glass"><button class="sec-head" data-sec>${t("otherGear",{n:Object.keys(alt).length})} ${ICON.chev}</button><div class="acc"><div><div style="padding:0 18px 12px">${Object.entries(alt).map(([g,s])=>`<div class="step"><b style="width:auto;padding:0 10px;border-radius:999px">${gearName(g)}</b><p>${s}</p></div>`).join("")}</div></div></div></div>`:""}
      ${tip?`<div class="tip"><b>${t("tip")}</b><span>${tip}</span></div>`:""}
    </div>`;
}
/* открытие рецепта без View Transition: снимок всей страницы (WebGL-аврора, blur) давал пустой кадр и летящий квадрат.
   Теперь только классы: .veil opacity 0->1 (200ms), .win translateX(40px) / translateY(100%) на телефоне -> 0 (320ms).
   Аврора на паузе, пока рецепт или режим готовки открыты; фокус уходит в окно и возвращается на кнопку */
let sheetT = 0;
const auroraHold = on => { if(window.AURORA && AURORA.pause) AURORA.pause(on); };
function openRecipe(id, trigger, mode){
  const r = byId(id); if(!r) return;
  if(!isOpen(r)) return openPaywall("recipe");
  sheetId = id; sheetMode = mode || ""; clearTimeout(sheetT);
  const sh = $("#sheet"), win = $("#win"), wasOpen = sh.classList.contains("on");
  if(!wasOpen) sheetSrc = trigger && trigger.focus ? trigger : document.activeElement;
  win.innerHTML = sheetMode==="left" ? leftHTML(r) : recipeHTML(r); win.scrollTop = 0; win.style.transform = ""; win.style.transition = "";
  sh.classList.add("on"); document.body.style.overflow = "hidden"; auroraHold(true);
  if(RM()) sh.classList.add("show");
  else { sh.classList.add("anim"); void win.offsetWidth; sh.classList.add("show"); sheetT = setTimeout(()=>sh.classList.remove("anim"), 360); }
  win.focus({preventScroll:true});
  /* отзывы (mod_reviews.js): лента под рецептом и сводка рядом с названием, если отзывы есть */
  if(window.DD_REVIEWS && sheetMode!=="left"){ DD_REVIEWS.renderFeed($("#ddFeed"), id); paintWinSum(id); }
}
function paintWinSum(id){
  DD_REVIEWS.summary(id).then(s=>{
    if(sheetId!==id || !$("#sheet").classList.contains("on")) return;
    let el = $("#winSum");
    if(!s || !s.n){ if(el) el.remove(); return; }
    if(!el){ el = document.createElement("div"); el.id = "winSum"; el.className = "win-sum"; $("#winTitle").after(el); }
    el.textContent = `★ ${dec(Math.round(s.avg*10)/10)} · ${s.worthPct}% ${t("worthIt")} · ${pn(s.n,"review")}`;
  }).catch(()=>{});
}
/* новый или удалённый отзыв: сводка у открытого рецепта обновляется сразу */
document.addEventListener("dd-reviews:change", ()=>{ if(window.DD_REVIEWS && sheetId && $("#sheet").classList.contains("on")) paintWinSum(sheetId); });
function closeRecipe(){
  const sh = $("#sheet"); if(!sh.classList.contains("on")) return;
  clearTimeout(sheetT);
  const done = ()=>{
    sh.classList.remove("on","anim");
    if(!$("#cook").classList.contains("on")){ document.body.style.overflow = ""; auroraHold(false); }
    const back = sheetSrc; sheetSrc = null; if(back && back.isConnected && back.focus) back.focus({preventScroll:true});
  };
  sh.classList.remove("show");
  if(RM()) return done();
  sh.classList.add("anim"); sheetT = setTimeout(done, 330);
}
/* фокус не уходит из окна рецепта по Tab */
document.addEventListener("keydown", e=>{
  if(e.key!=="Tab" || !$("#sheet").classList.contains("on") || $("#cook").classList.contains("on")) return;
  const f = [...$("#win").querySelectorAll("button,a[href],input,select")].filter(x=>!x.disabled && x.getClientRects().length);
  if(!f.length) return;
  const first = f[0], last = f[f.length-1], a = document.activeElement;
  if(e.shiftKey && (a===first || a===$("#win"))){ e.preventDefault(); last.focus(); }
  else if(!e.shiftKey && a===last){ e.preventDefault(); first.focus(); }
});

/* ================= ГОТОВКА ================= */
let cook = null, timer = null;
function openCook(id, e){
  const r = byId(id); if(!r) return; cook = {r, i:0};
  clearTimeout(sheetT); $("#sheet").classList.remove("on","show","anim");
  document.body.style.overflow = "hidden"; auroraHold(true); $("#cook").classList.add("on"); drawCook(0);
  $("#cookNext").focus({preventScroll:true});
}
function drawCook(dir){
  const r = cook.r, how = rhow(r), n = how.length;
  cook.i = Math.min(cook.i, n-1); const i = cook.i;
  $("#cookArt").innerHTML = dishArt(r); $("#cookDish").textContent = rn(r); $("#cookDish").style.cssText = "font-size:19px;"+useFont(r.cu); $("#cookCount").textContent = t("cookStepOf",{n:i+1, m:n});
  $("#cookDots").innerHTML = how.map((_,k)=>`<i class="${k<=i?"done":""}"></i>`).join("");
  const mins = (how[i].match(/(\d+)\s*(?:минут|min)/i)||[])[1];
  $("#cookStep").innerHTML = `<div class="n grad-text num" id="cookN">${String(i+1).padStart(2,"0")}</div><div class="txt" id="cookTxt">${how[i]}</div>
    ${mins?`<button class="timer" id="timerBtn" data-min="${mins}"><span class="tr"><svg viewBox="0 0 50 50"><circle class="bgc" cx="25" cy="25" r="20"/><circle class="fg" id="timerFg" cx="25" cy="25" r="20" stroke-dasharray="125.7" stroke-dashoffset="0"/></svg></span><span id="timerTxt">${t("timerN",{n:mins})}</span></button>`:""}
    ${i===0?`<div class="cook-ings">${Object.keys(r.ing).map(k=>`<span class="chip sm">${ingName(k)} · ${qty(r.ing[k]*scale(),ING[k].u)}</span>`).join("")}</div>`:""}`;
  if(dir && !RM()){ $("#cookStep").animate([{opacity:0,transform:`translateX(${dir*80}px)`,filter:"blur(14px)"},{opacity:1,transform:"none",filter:"blur(0)"}],{duration:620,easing:"cubic-bezier(.22,1,.36,1)"}); }
  F.odometer($("#cookN"), String(i+1).padStart(2,"0"));
  $("#cookPrev").disabled = i===0; $("#cookNext").textContent = i===n-1 ? t("doneEnjoy") : t("doneNext");
  stopTimer();
}
function stopTimer(){ if(timer){ clearInterval(timer); timer = null; } }
function startTimer(btn){
  const total = +btn.dataset.min*60; let left = total; btn.classList.add("run"); stopTimer();
  timer = setInterval(()=>{ left--; $("#timerTxt").textContent = `${String(Math.floor(left/60)).padStart(2,"0")}:${String(left%60).padStart(2,"0")}`; $("#timerFg").style.strokeDashoffset = String(125.7*(1-left/total));
    if(left<=0){ stopTimer(); btn.classList.remove("run"); $("#timerTxt").textContent = t("timeUp"); toast(t("timeUpX",{x:rn(cook.r)})); const b=btn.getBoundingClientRect(); F.confetti(b.left+24,b.top+24,{count:60}); } }, 1000);
}
function closeCook(){ stopTimer(); $("#cook").classList.remove("on"); document.body.style.overflow = ""; auroraHold(false); const back = sheetSrc; sheetSrc = null; if(back && back.isConnected && back.focus) back.focus({preventScroll:true}); }
$("#cook").addEventListener("click", e=>{
  const b = e.target.closest("button"); if(!b) return;
  if(b.id==="cookClose") return closeCook(e);
  if(b.id==="timerBtn") return startTimer(b);
  if(b.id==="cookPrev" && cook.i>0){ cook.i--; return drawCook(-1); }
  if(b.id==="cookNext"){ if(cook.i<rhow(cook.r).length-1){ cook.i++; drawCook(1); } else { const rid = cook.r.id; F.confetti(innerWidth/2, innerHeight/2, {count:180}); setTimeout(()=>{ closeCook(); S.cooked = {...(S.cooked||{}), [rid]:Date.now()}; save(); renderPlan(); if(window.DD_REVIEWS) DD_REVIEWS.openCooked(rid); else toast(t("enjoy")); }, 700); } }
});

/* ================= НАВИГАЦИЯ ================= */
const TITLES = new Proxy({}, {get:(_,k)=>t("title_"+String(k))});
let curTab = "plan", dockCtl = null;
function moveInd(){
  const cur = $("#dock [aria-current=page]"); if(!cur || !cur.offsetWidth){ $("#dockInd").style.width = "0px"; return; }
  if(dockCtl && dockCtl.move) return dockCtl.move(cur);
  const d = $("#dock").getBoundingClientRect(), b = cur.getBoundingClientRect();
  $("#dockInd").style.width = b.width+"px"; $("#dockInd").style.transform = `translateX(${b.left-d.left}px)`;
}
function setTab(tab){
  curTab = tab;
  $$("#dock button").forEach(x=> x.dataset.tab===tab ? x.setAttribute("aria-current","page") : x.removeAttribute("aria-current"));
  $$(".pane").forEach(p=>p.classList.toggle("on", p.id==="pane-"+tab));
  /* чипы меню недели (порции, ужины, бюджет) нужны только экранам меню, не соцчасти и настройкам */
  $("#headChips").hidden = ["community","profile","set"].includes(tab);
  $("#appTitle").textContent = TITLES[tab]; window.scrollTo(0,0); requestAnimationFrame(moveInd);
  paintSocial(tab);
}
/* соцчасть (mod_reviews.js): лента и профиль рисуются при открытии своей вкладки */
function paintSocial(tab){
  if(!window.DD_REVIEWS) return;
  if(tab==="community") DD_REVIEWS.renderCommunity($("#ddCommunity"));
  if(tab==="profile") DD_REVIEWS.renderProfile($("#ddProfile"));
}
document.addEventListener("dd-reviews:profile", ()=>{ if($("#app").classList.contains("on")) switchTab("profile"); });
document.addEventListener("dd-reviews:cook", ()=>switchTab("plan"));
function switchTab(tab, e){
  if(tab===curTab) return;
  $$("#dock button").forEach(x=> x.dataset.tab===tab ? x.setAttribute("aria-current","page") : x.removeAttribute("aria-current")); moveInd();
  F.shutter(()=>setTab(tab), {...at(e), label:TITLES[tab]}).then(()=>{
    F.kinetic($("#appTitle"), TITLES[tab]);
    const pane = $("#pane-"+tab);
    F.reveal([...pane.querySelectorAll(".glass")].filter(el=>el.getBoundingClientRect().top < innerHeight).slice(0,14), {step:55});
    F.observe(pane, ".glass, .flip");
  });
}
$("#dock").addEventListener("click", e=>{ const b = e.target.closest("button"); if(b) switchTab(b.dataset.tab, e); });
addEventListener("resize", moveInd);

/* ================= СОБЫТИЯ ================= */
function rerenderAfterPrefs(){ renderHead(); renderMeals(); renderFridge(); renderSettings(); }
$("#app").addEventListener("click", e=>{
  const b = e.target.closest("button, a"); if(!b) return;
  const d = b.dataset;
  if(b.closest("#pane-nutri") && nutriClick(b, e)) return;
  if(d.sort){ window.__sort = d.sort; window.__limit = 24; return renderMeals(); }
  if(exclClick(b, $("#setExcl"), "s")){ renderHead(); renderMeals(); renderFridge(); $("#setSummary") && renderSettings(); toast(t("restrUpdated")); return; }
  if(d.cook) return openCook(d.cook, e);
  if(d.flip){ b.closest(".flip").classList.toggle("flipped"); return; }
  if(d.open) return openRecipe(d.open, b);
  if(d.left3) return openRecipe(d.left3, b, "left");
  if(d.expand!==undefined){ $(`#days .day[data-day-i="${d.expand}"]`).classList.toggle("open"); return; }
  if(d.jump) return switchTab(d.jump, e);
  if(d.showall){ window.__showAll = !window.__showAll; return renderMeals(); }
  if(d.addplan){ S.plan[Math.max(0,S.plan.length-1)] = d.addplan; save(); renderPlan(); renderList(); renderMeals(); toast(t("addedEnd")); return; }
  if(d.swap!==undefined){
    const i = +d.swap, cur = S.plan[i];
    const alts = pool().filter(r=>!S.plan.includes(r.id)).map(r=>({r,s:score(r)})).sort((a,c)=>c.s-a.s).slice(0,8);
    if(!alts.length){ toast(S.cuisines.length ? t("noOtherCu") : t("noFree")); return; }
    const next = rnd(alts).r.id, row = b.closest(".day");
    const doIt = ()=>{ S.plan = S.plan.map(x=>x===cur ? next : x); save(); renderPlan(); renderList(); renderHead(); };
    if(row && !RM()){
      row.animate([{opacity:1,transform:"none",filter:"blur(0)"},{opacity:0,transform:"rotateX(70deg) translateY(20px)",filter:"blur(8px)"}],{duration:300,easing:"ease-in",fill:"forwards"}).finished.then(()=>{ doIt();
        const nr = $(`#days .day[data-day-i="${i}"]`); if(nr) nr.animate([{opacity:0,transform:"rotateX(-70deg) translateY(-20px)",filter:"blur(8px)"},{opacity:1,transform:"none",filter:"blur(0)"}],{duration:620,easing:"cubic-bezier(.34,1.56,.64,1)"}); });
    } else doIt();
    toast(t("swapped",{a:rn(byId(cur)), b:rn(byId(next))})); return;
  }
  if(d.buy){
    S.bought[d.buy] = !S.bought[d.buy]; save(); b.classList.toggle("got", !!S.bought[d.buy]);
    const rows = basket(S.plan), got = rows.filter(r=>S.bought[r.key]).length, pct = rows.length?got/rows.length:0;
    ringTo($("#listFg"), pct, 314); $("#listPct").textContent = Math.round(pct*100)+"%"; $("#listProgress").textContent = t("inCart",{a:got, b:rows.length, c:tr(activeChain())});
    const cat = b.closest(".cat"); if(cat) cat.querySelector(".cnt").textContent = t("aOfB",{a:cat.querySelectorAll(".item.got").length, b:cat.querySelectorAll(".item").length});
    if(pct===1){ toast(t("allBought")); F.confetti(innerWidth/2, innerHeight*.35, {count:200}); }
    return;
  }
  if(d.togglecat){ const c = b.closest(".cat"); c.classList.toggle("open"); c.classList.contains("open") ? window.__openCats.add(d.togglecat) : window.__openCats.delete(d.togglecat); return; }
  if(d.cuf!==undefined){ window.__cuF = d.cuf; window.__limit = 24; return renderMeals(); }
  if(d.mf!==undefined){ window.__mF = d.mf; window.__limit = 24; return renderMeals(); }
  if(b.id==="moreMeals"){ window.__limit = (window.__limit||24)+24; return renderMeals(); }
  if(d.addfr){ if(!S.fridge.includes(d.addfr)) S.fridge.push(d.addfr); save(); $("#frInput").value = ""; $("#frSuggest").classList.remove("on"); renderFridge(); toast(t("xAdded",{x:ingName(d.addfr)})); return; }
  if(d.delfr){ S.fridge = S.fridge.filter(x=>x!==d.delfr); save(); return renderFridge(); }
  if(b.id==="spinBtn" || b.id==="spinAgain") return spin(e);
  if(b.id==="planFromFridge"){ if(S.fridge.length<2){ toast(t("addTwo")); return; } S.rules.fridgeFirst = true; save(); return buildWeek(e); }
  if(d.rule){ S.rules[d.rule] = !S.rules[d.rule]; save(); b.setAttribute("aria-pressed", S.rules[d.rule]); renderPlan(); toast(S.rules[d.rule] ? t("ruleOn") : t("ruleOff")); return; }
  if(d.setchain){ S.chain = d.setchain; save(); renderApp(); moveInd(); toast(d.setchain==="auto"?t("cheapestChain"):t("pinnedX",{x:tr(chainOf(d.setchain))})); return; }
  if(d.setcu){ S.cuisines = S.cuisines.includes(d.setcu) ? S.cuisines.filter(x=>x!==d.setcu) : [...S.cuisines, d.setcu]; save(); renderSettings(); renderHead(); return; }
  if(d.setcuall){ S.cuisines = []; save(); renderSettings(); renderHead(); return; }
  if(b.id==="photoSw"){ S.photos = !S.photos; save(); renderApp(); moveInd(); return; }
  if(b.id==="copyList"){ const rows = basket(S.plan); const txt = t("listHead",{c:tr(activeChain())}) + "\n" + rows.map(r=>`- ${ingName(r.key)}: ${qty(r.buy,r.g.u)}`).join("\n") + "\n" + t("listTotal",{x:rub(basketSum(rows))}); navigator.clipboard?.writeText(txt).then(()=>toast(t("copied")),()=>toast(t("copyFail"))); return; }
  if(b.id==="redo") return buildWeek(e);
  if(b.id==="reset"){ F.shutter(()=>{ S = {...structuredClone(DEF), lang:S.lang, access:S.access}; applyCountry(REGION.cc); save(); step = 0; show("onb"); drawStep(); }, {...at(e), label:t("freshStart")}); return; }
});
$("#app").addEventListener("input", e=>{ if(e.target.id==="sExIn") exclSuggest("s"); if(["ndSearch","nfSearch","nfGrams"].includes(e.target.id)) renderAddResults(); });
$("#app").addEventListener("change", e=>{
  const rm = e.target.dataset.rm, rn_ = e.target.dataset.rmnum;
  if(rm){ S.nutri.remind[rm] = +e.target.value; save(); return; }
  if(rn_){ const v = Math.round(+e.target.value||0), lim = rn_==="kcalGoal" ? [800,6000] : [1,20]; S.nutri[rn_] = v ? Math.min(lim[1], Math.max(lim[0], v)) : 0; save(); renderNutri(); return; }
  const k = e.target.dataset.pnum; if(k){ const v = parseFloat(String(e.target.value).replace(",", ".")); if(v>0){ S.nutri.profile[k] = v; save(); renderNutri(); } } });
$("#app").addEventListener("keydown", e=>{ if(e.target.id==="sExIn" && e.key==="Enter"){ const f=$("#sExSug [data-exadd]"); if(f) f.click(); } if(e.target.id==="frInput" && e.key==="Enter"){ const f=$("#frSuggest [data-addfr]"); if(f) f.click(); } });
let mealT;
$("#mealSearch").addEventListener("input", ()=>{ clearTimeout(mealT); mealT = setTimeout(()=>{ window.__limit = 24; renderMeals(); }, 160); });
$("#frInput").addEventListener("input", frSuggest);
document.addEventListener("click", e=>{ if(!e.target.closest(".fr-input")) $("#frSuggest").classList.remove("on"); if(!e.target.closest(".search-wrap")) $$(".suggest").forEach(s=>{ if(s.id!=="frSuggest") s.classList.remove("on"); }); });
$("#sheet").addEventListener("click", e=>{
  const b = e.target.closest("[data-close],[data-add],[data-cook],[data-sec],[data-todiary],[data-left3],[data-openrec],[data-leftbuy]"); if(!b) return;
  if(b.dataset.left3) return openRecipe(b.dataset.left3, null, "left");
  if(b.dataset.openrec) return openRecipe(b.dataset.openrec);
  if(b.dataset.leftbuy){
    const k = b.dataset.leftbuy, [id, i] = k.split(":"), r = byId(id), o = r && next3(r)[+i]; if(!o) return;
    S.extra = S.extra || {};
    if(S.extra[k]) delete S.extra[k]; else S.extra[k] = o.ing;
    save(); toast(t(S.extra[k] ? "left3Added" : "left3Removed"));
    $("#win").innerHTML = leftHTML(r); const nb = $(`#win [data-leftbuy="${k}"]`); if(nb) nb.focus();
    if($("#app").classList.contains("on")){ renderPlan(); renderList(); }
    return;
  }
  if(b.dataset.todiary && !canNutriNow()){ closeRecipe(); if($("#app").classList.contains("on")) switchTab("nutri"); else openPaywall(); return; }
  if(b.dataset.todiary && !S.nutri.consent){ closeRecipe(); toast(t("hcAsk")); if($("#app").classList.contains("on")) switchTab("nutri"); return; }
  if(b.dataset.todiary){ const r = byId(b.dataset.todiary), m = mealByHour(); addEntry(dkey(new Date()), dishEntry(r, 1, m)); renderNutri(); toast(t("loggedDiary",{m:mealName(m).toLowerCase()})); return; }
  if(b.dataset.cook) return openCook(b.dataset.cook, e);
  if(b.dataset.sec!==undefined){ b.closest(".sec").classList.toggle("open"); return; }
  if(b.dataset.add!==undefined){ if(S.plan.length < S.days.length) S.plan.push(b.dataset.add); else S.plan[S.plan.length-1] = b.dataset.add; save(); closeRecipe(); renderApp(); moveInd(); toast(t("addedEnd")); return; }
  closeRecipe();
});
document.addEventListener("keydown", e=>{ if(e.key!=="Escape") return; if($("#cook").classList.contains("on")) closeCook(); else if($("#sheet").classList.contains("on")) closeRecipe(); });
let toastT;
function toast(msg){ $("#toastTxt").textContent = msg; $("#toast").classList.add("on"); clearTimeout(toastT); toastT = setTimeout(()=>$("#toast").classList.remove("on"), 2800); }

/* ================= ЯЗЫК: переключение без перезагрузки ================= */
function applyStatic(){
  document.documentElement.lang = S.lang;
  $$("[data-i18n]").forEach(el=>{ el.textContent = t(el.dataset.i18n); });
  $$("[data-i18n-html]").forEach(el=>{ el.innerHTML = t(el.dataset.i18nHtml); });
  $$("[data-i18n-ph]").forEach(el=>{ el.placeholder = t(el.dataset.i18nPh); });
  $$("[data-i18n-aria]").forEach(el=>{ el.setAttribute("aria-label", t(el.dataset.i18nAria)); });
  $$("[data-i18n-cur]").forEach(el=>{ el.dataset.cursor = t(el.dataset.i18nCur); });
  $$(".lang-pill b").forEach(b=>b.classList.toggle("on", b.dataset.l===S.lang));
}
function setLang(l){
  if(!LANGS.includes(l) || l===S.lang) return;
  S.lang = l; save(); applyStatic(); paintStores();
  if(window.RACE && RACE.destroy) RACE.destroy($("#race"));
  if($("#app").classList.contains("on")){ renderApp(); $("#appTitle").textContent = TITLES[curTab]; requestAnimationFrame(moveInd); }
  if($("#onb").classList.contains("on")) drawStep();
  if($("#sheet").classList.contains("on") && sheetId) $("#win").innerHTML = sheetMode==="left" ? leftHTML(byId(sheetId)) : recipeHTML(byId(sheetId));
  if($("#cook").classList.contains("on") && cook) drawCook(0);
  if(siteReady) renderSite();
  if($("#legal").classList.contains("on") && legalDoc) renderLegal();
  if($("#pay").classList.contains("on") && !$("#payForm").hidden) renderPay();
  if($("#build").classList.contains("on") && !building) $("#buildTitle").textContent = t("building");
}
document.addEventListener("click", e=>{ const b = e.target.closest("[data-langtoggle],[data-setlang]"); if(b) setLang(b.dataset.setlang || (S.lang==="ru" ? "en" : "ru")); });

/* ================= ЖЕСТЫ НА ТЕЛЕФОНЕ ================= */
(function(){
  let sx = 0, sy = 0, st = 0, armed = false;
  document.addEventListener("touchstart", e=>{
    const tc = e.touches[0]; sx = tc.clientX; sy = tc.clientY; st = Date.now();
    armed = !!e.target.closest("#app .wrap") && !e.target.closest(".scroller,.cu-cloud,.addres,input,textarea,.marq,.chart,.fr-input,.head-chips,.flip")
      && !$("#sheet").classList.contains("on") && !$("#cook").classList.contains("on");
  }, {passive:true});
  document.addEventListener("touchend", e=>{
    if(!armed) return; armed = false;
    const tc = e.changedTouches[0], dx = tc.clientX-sx, dy = tc.clientY-sy;
    if(Math.abs(dx) < 80 || Math.abs(dx) < Math.abs(dy)*1.6 || Date.now()-st > 700) return;
    const order = [...document.querySelectorAll("#dock button")].map(b=>b.dataset.tab), j = order.indexOf(curTab) + (dx<0 ? 1 : -1);
    if(j<0 || j>=order.length) return;
    switchTab(order[j], {clientX: dx<0 ? innerWidth-24 : 24, clientY: innerHeight/2});
  }, {passive:true});

  const win = $("#win"); let wy = 0, wd = 0, drag = false;
  win.addEventListener("touchstart", e=>{ if(innerWidth>700 || win.scrollTop>0) return; drag = true; wy = e.touches[0].clientY; wd = 0; win.style.transition = "none"; }, {passive:true});
  win.addEventListener("touchmove", e=>{ if(!drag) return; wd = Math.max(0, e.touches[0].clientY-wy); win.style.transform = wd>0 ? `translateY(${wd}px)` : ""; }, {passive:true});
  win.addEventListener("touchend", ()=>{
    if(!drag) return; drag = false;
    win.style.transition = "transform .45s cubic-bezier(.22,1,.36,1)";
    if(wd>110){ win.style.transform = "translateY(100%)"; setTimeout(()=>{ closeRecipe(); win.style.transform = ""; win.style.transition = ""; }, 280); }
    else win.style.transform = "";
  });

  const ck = $("#cook"); let cx0 = 0, cy0 = 0;
  ck.addEventListener("touchstart", e=>{ cx0 = e.touches[0].clientX; cy0 = e.touches[0].clientY; }, {passive:true});
  ck.addEventListener("touchend", e=>{
    if(!cook || e.target.closest("button")) return;
    const dx = e.changedTouches[0].clientX-cx0, dy = e.changedTouches[0].clientY-cy0;
    if(Math.abs(dx)<70 || Math.abs(dx)<Math.abs(dy)*1.5) return;
    if(dx<0 && cook.i<rhow(cook.r).length-1){ cook.i++; drawCook(1); }
    else if(dx>0 && cook.i>0){ cook.i--; drawCook(-1); }
  }, {passive:true});
})();

/* ================= ЛОГОТИП: на главную ================= */
/* в приложении у оплатившего - главный экран приложения (неделя), иначе - верх сайта. Ответы анкеты уже сохранены в S */
function goHome(){
  if($("#cook").classList.contains("on")) closeCook();
  if($("#sheet").classList.contains("on")) closeRecipe();
  if($("#app").classList.contains("on") && canEnter()){
    if(curTab!=="plan") setTab("plan"); else scrollTo({top:0, behavior:RM()?"auto":"smooth"});
    $("#appTitle").focus && $("#appTitle").setAttribute("tabindex","-1"); $("#appTitle").focus({preventScroll:true});
    return;
  }
  if($("#site").classList.contains("on")){ scrollToId("top"); history.replaceState(null, "", location.pathname + location.search); return; }
  if(SPLIT && ENTRY==="app") return goSite("top");
  go("site", ()=>{ scrollTo(0,0); $("#heroH").setAttribute("tabindex","-1"); $("#heroH").focus({preventScroll:true}); });
}

/* ================= ЮРИДИЧЕСКИЕ ВКЛАДКИ ================= */
/* #privacy #terms #offer #cookies #consents и якоря разделов #doc-sN. Тексты и константа REQUISITES в mod_legal.js, плашка проверки включается DD_LEGAL.draft=true */
let legalDoc = null, legalReturn = null;
function legalParse(h){ const m = /^(privacy|terms|offer|cookies|consents)(?:-s(\d+))?$/.exec(h||""); return m ? {doc:m[1], sec:m[2] ? +m[2] : 0} : null; }
/* таблица цен в оферте считается той же формулой, что сайт и сервер (BYN) */
function priceTableHTML(en){
  const T = DD_PAY.TERMS, row = plan => `<tr><td>${planName(plan)}</td>${T.map(m=>`<td class="num">${DD_PAY.priceFor(plan, m, "BY").total} BYN</td>`).join("")}</tr>`;
  return `<div class="lg-table"><table><tr><th>${en ? "Plan" : "Тариф"}</th>${T.map(m=>`<th>${m} ${en ? "mo" : "мес"}</th>`).join("")}</tr>${row("plus")}${row("pro")}</table></div>`;
}
const legalFill = s => s.replace("%%PRICES_RU%%", priceTableHTML(false)).replace("%%PRICES_EN%%", priceTableHTML(true));
function renderLegal(){
  const L = DD_LEGAL, pick = id => S.lang==="en" ? L.docs[id].en : L.docs[id].ru, doc = pick(legalDoc), wide = matchMedia("(min-width: 981px)").matches;
  $("#lgMain").innerHTML = `
    <nav class="lg-docs" aria-label="${t("lgDocsNav")}">${L.order.map(id=>`<a href="#${id}"${id===legalDoc?' aria-current="page"':""}>${escH(pick(id).short)}</a>`).join("")}</nav>
    <header class="lg-head">
      <p class="lg-kick">${t("lgKicker")}</p>
      <h1>${escH(doc.t)}</h1>
      <div class="lg-meta"><span class="lg-ed">${t("lgEdition",{d:L.date})}</span>${L.draft ? `<span class="lg-draft">${t("lgDraft")}</span>` : ""}</div>
      ${REGION.cc!=="BY" ? `<p class="lg-cc">${t("lgCountry")}</p>` : ""}
      <p class="lg-lead">${escH(doc.lead)}</p>
    </header>
    <div class="lg-grid">
      <aside class="lg-aside"><details class="lg-toc"${wide?" open":""}><summary>${t("lgToc")}</summary><ol>${doc.s.map((s,i)=>`<li><a href="#${legalDoc}-s${i+1}"><span class="num">${i+1}</span>${escH(s[0])}</a></li>`).join("")}</ol></details></aside>
      <article class="lg-doc">
        ${doc.s.map((s,i)=>`<section class="lg-sec" id="${legalDoc}-s${i+1}" tabindex="-1" aria-labelledby="${legalDoc}-h${i+1}"><h2 id="${legalDoc}-h${i+1}"><span class="lg-n num" aria-hidden="true">${i+1}</span>${escH(s[0])}</h2>${legalFill(s[1])}</section>`).join("")}
        <section class="lg-other"><h2>${t("lgOther")}</h2><div class="lg-other-g">${L.order.filter(id=>id!==legalDoc).map(id=>`<a class="glass" href="#${id}"><b>${escH(pick(id).t)}</b><span>${t("docOpen")}</span></a>`).join("")}</div></section>
      </article>
    </div>`;
  const back = $("#lgBack"); back.textContent = t(legalReturn==="pay" ? "lgToPay" : "lgToSite"); back.setAttribute("href", legalReturn==="pay" ? "#pay" : "#top");
}
function openLegal(doc, sec, write){
  const was = $("#legal").classList.contains("on");
  if(!was) show("legal");
  if(legalDoc!==doc || !was){ legalDoc = doc; renderLegal(); }
  const id = sec ? `${doc}-s${sec}` : "";
  if(write!==false) history.replaceState(null, "", "#" + (id || doc));
  requestAnimationFrame(()=>{
    const el = id && document.getElementById(id);
    if(el){ el.scrollIntoView({block:"start", behavior:"auto"}); el.focus({preventScroll:true}); if(!matchMedia("(min-width: 981px)").matches){ const d = $(".lg-toc"); if(d) d.open = false; } }
    else { scrollTo(0,0); $("#lgMain").focus({preventScroll:true}); }
  });
}
document.addEventListener("click", e=>{
  const a = e.target.closest("a[href^='#']"); if(!a) return;
  const p = legalParse(a.getAttribute("href").slice(1)); if(!p) return;
  e.preventDefault();
  /* из приложения документы открываются на сайте; со страницы оплаты - в новой вкладке, чтобы не потерять форму */
  if(SPLIT && ENTRY==="app"){ const u = "../#" + a.getAttribute("href").slice(1); return a.closest("#pay") ? void window.open(u, "_blank", "noopener") : location.assign(u); }
  if(!a.closest("#legal")){ const cur = $(".screen.on"); legalReturn = a.closest("#payAgreeTxt") ? "pay" : cur ? cur.id : null; }
  openLegal(p.doc, p.sec);
});
$("#lgBack").addEventListener("click", e=>{
  if(legalReturn==="pay"){ e.preventDefault(); e.stopPropagation(); legalReturn = null; openPay(payPlan).then(()=>$("#payAgree").focus({preventScroll:true})); }
  else if(legalReturn==="app" && canEnter()){ e.preventDefault(); e.stopPropagation(); legalReturn = null; show("app"); requestAnimationFrame(moveInd); }
});
$("#lgUp").addEventListener("click", e=>{ e.preventDefault(); scrollTo({top:0, behavior:RM()?"auto":"smooth"}); $("#lgMain").focus({preventScroll:true}); });
addEventListener("scroll", ()=>{ if($("#legal").classList.contains("on")) $("#lgUp").hidden = scrollY < 600; }, {passive:true});

/* ================= СОГЛАСИЕ НА COOKIE ================= */
/* dd_consent = {v, date, necessary, analytics}. Аналитика грузится только при DD_CONSENT.has('analytics') */
function cookieInit(){
  const bar = $("#cookieBar"), dlg = $("#cookieDlg"), root = document.documentElement;
  const size = () => root.style.setProperty("--cbh", bar.hidden ? "0px" : (bar.offsetHeight + 12) + "px");
  const setBar = on => { bar.hidden = !on; root.classList.toggle("cb-on", on); size(); };
  if(window.ResizeObserver) new ResizeObserver(size).observe(bar);
  let opener = null;
  const decide = analytics => { DD_CONSENT.set({analytics}); const had = !bar.hidden; setBar(false); toastSafe(t("cdSaved")); if(had && document.activeElement===document.body) $(".screen.on") && ($(".screen.on").querySelector("a,button")||document.body).focus({preventScroll:true}); };
  DD_CONSENT.open = () => {
    opener = document.activeElement; const c = DD_CONSENT.get(); $("#cdAna").checked = !!(c && c.analytics);
    if(dlg.showModal) dlg.showModal(); else dlg.setAttribute("open", "");
  };
  dlg.addEventListener("close", ()=>{
    const v = dlg.returnValue; dlg.returnValue = "";
    if(v==="save" || v==="all"){ if(v==="all") $("#cdAna").checked = true; decide($("#cdAna").checked); }
    if(opener && opener.isConnected && opener!==document.body) opener.focus({preventScroll:true});
  });
  dlg.addEventListener("click", e=>{ if(e.target===dlg) dlg.close("cancel"); });
  bar.addEventListener("click", e=>{ const b = e.target.closest("[data-cb]"); if(!b) return; if(b.dataset.cb==="config") return DD_CONSENT.open(); decide(b.dataset.cb==="all"); });
  document.addEventListener("click", e=>{ if(e.target.closest("[data-cookieset]")) DD_CONSENT.open(); });
  setBar(!DD_CONSENT.get());
}

/* ================= НАПОМИНАНИЯ О ВОДЕ ================= */
/* в открытой вкладке - тост с «+250 мл»; если разрешено и вкладка в фоне - системное уведомление.
   Вне открытой вкладки без установленного PWA не работает, об этом честно сказано в настройках.
   Для проверки: DD_REMIND.test(3000) - интервал 3 секунды */
let wToastT = 0, remindTestMs = 0;
const inHours = (h, a, b) => a===b ? false : a < b ? h >= a && h < b : h >= a || h < b;
function remindTick(){
  const R = S.nutri.remind; if(!R || !R.on || !canNutriNow() || !S.nutri.consent) return;
  const now = new Date(), h = now.getHours() + now.getMinutes()/60;
  if(!inHours(h, R.from, R.to) || inHours(h, R.qFrom, R.qTo)) return;
  if(Date.now() - (R.last||0) < (remindTestMs || R.every*60000)) return;
  R.last = Date.now(); save(); fireWater();
}
function fireWater(){
  if(document.hidden && "Notification" in window && Notification.permission==="granted"){ try{ new Notification("Dishday", {body:t("drinkNow"), tag:"dd-water"}); }catch(e){} }
  const w = $("#wToast"); w.classList.add("on"); clearTimeout(wToastT); wToastT = setTimeout(()=>w.classList.remove("on"), 20000);
}
$("#wToast").addEventListener("click", e=>{
  const b = e.target.closest("button"); if(!b) return;
  $("#wToast").classList.remove("on");
  if(b.id!=="wPlus") return;
  if(!S.nutri.consent){ toast(t("hcAsk")); return; }
  const key = dkey(new Date()), cups = (S.nutri.water[key]||0) + 1; S.nutri.water[key] = cups; save();
  if($("#app").classList.contains("on")) renderNutri();
  toast(t("waterAdded",{a:cups, b:nutriNorm().water}));
});
setInterval(remindTick, 5000);
document.addEventListener("visibilitychange", ()=>{ if(!document.hidden) remindTick(); });
window.DD_REMIND = {test(ms){ remindTestMs = ms||0; S.nutri.remind.last = 0; remindTick(); }, tick:remindTick, fire:fireWater};

/* поле ввода не прячется под клавиатурой и нижней панелью на телефоне */
document.addEventListener("focusin", e=>{
  if(!e.target.matches("input:not([type=checkbox]):not([type=range]),select,textarea") || innerWidth > 760) return;
  setTimeout(()=>e.target.scrollIntoView({block:"center", behavior:"auto"}), 300);
});

/* ================= СТАРТ ================= */
if(!RM()) document.documentElement.classList.add("motion");
{ const d = detectCountry(); applyCountry(d.cc, d.how, d.soon); }
applyTheme(); applyStatic(); paintStores(); if(window.AURORA) AURORA.init($("#aurora")); F.inter(); cookieInit();
if(window.DD_REVIEWS) DD_REVIEWS.plusUntil().then(ms=>{ ms = +ms||0; if(ms!==(S.bonusUntil||0)){ S.bonusUntil = ms; save(); if(siteReady) renderSite(); } }).catch(()=>{});
if(FXM.liquidDock) dockCtl = FXM.liquidDock($("#dock"), $("#dockInd"));
function openAppFlow(){
  if(SPLIT && ENTRY==="site") return toApp();
  if(!canEnter()) return freeOver() ? openPaywall() : goSite("join");
  if(askGeo(openAppFlow)) return;
  if(S.done && S.plan.some(id=>{ const r = byId(id); return !r || !dietOk(r) || (S.cuisines.length && !S.cuisines.includes(r.cu)); })){ S.plan = pickPlan(); save(); }
  if(S.done && S.plan.length){ show("app"); renderApp(); setTab("plan"); F.kinetic($("#appTitle"), TITLES.plan); F.reveal([$("#heroSlot"), ...$$("#days .day"), ...$$("#pane-plan .side .panel")], {step:70}); F.observe($("#pane-plan"), ".glass"); requestAnimationFrame(moveInd); }
  else { step = 0; show("onb"); drawStep(); F.reveal([$("#onbLeft"), $(".o-card")], {step:160, y:30}); }
}
/* #app, #onb, #build без оплаты уводят на сайт; #pay открывает оплату */
function route(h){
  if(h==="pay") return openPay(payPlan);
  if(!canEnter()) return show("site");
  if(h==="onb"){ if(askGeo(()=>route(h))) return; step = 0; show("onb"); drawStep(); return; }
  openAppFlow();
}
/* ссылка «Поделиться»: #recipe=<id> открывает рецепт поверх текущего экрана */
function openRecipeHash(){
  const m = location.hash.match(/^#recipe=([a-z0-9_]{1,64})$/); if(!m) return false;
  history.replaceState(null, "", location.pathname + location.search);
  if(byId(m[1])) openRecipe(m[1]);
  return true;
}
addEventListener("hashchange", ()=>{ if(openRecipeHash()) return; const h = location.hash.slice(1), lp = legalParse(h); if(lp) return legalOut(h) || openLegal(lp.doc, lp.sec, false); if(h==="pay" || GATED.includes(h)) return route(h);
  if(SITE_ANCHORS.includes(h) && !$("#site").classList.contains("on")) goSite(h); });
/* восстановление доступа на другом устройстве: ссылка из письма restore, #restore=<token>.
   Email ссылка не несёт (в письме - только token), поэтому спрашиваем его на месте. */
function tryRestoreHash(){
  const m = location.hash.match(/^#restore=([^&]+)$/);
  if(!m || DD_PAY.config.mode !== "live") return false;
  history.replaceState(null, "", location.pathname + location.search);
  const token = decodeURIComponent(m[1]), email = (prompt(t("restoreEmailPrompt")) || "").trim().toLowerCase();
  if(email) DD_PAY.access(email, token).then(r=>{
    if(r.active && r.paid_until){
      S.access = {plan:r.plan, orderId:"", paidAt:Date.now(), until:Date.parse(r.paid_until) || 0, email, token};
      save(); F.shutter(openAppFlow);
    } else toastSafe(t("restoreFail"));
  });
  return true;
}
/* доступ мог протухнуть или отозваться на сервере, пока устройство было офлайн - при
   старте в live-режиме сверяем email+token и снимаем S.access только по явному active:false,
   сетевая ошибка (access() отдаёт active:true) доступ не трогает */
/* план и сроки берём у сервера: оплата - Pay.gs, пробный и бесплатный - Code.gs. Локальный флаг только рисует */
function recheckAccessOnBoot(){
  const after = () => { save(); if(!canEnter() && GATED.some(id=>$("#"+id).classList.contains("on"))) show("site"); if($("#app").classList.contains("on")) renderApp(); };
  const a = S.access;
  if(a && a.token && a.src==="wl") DD_PAY.wl.access(a.email, a.token).then(r=>{
    if(r.active === false){ S.access = null; return after(); }
    if(r.plan && r.plan!=="trial"){ S.access = null; if(r.free_end) S.free = {...(S.free||{email:a.email, start:Date.now(), token:a.token}), end:r.free_end}; after(); }
  });
  else if(DD_PAY.config.mode === "live" && a && a.token && a.until > Date.now()) DD_PAY.access(a.email, a.token).then(r=>{
    if(r.active === false){ S.access = null; return after(); }
    if(r.plan && DD_PAY.USD[r.plan]){ S.access.plan = r.plan; if(Date.parse(r.paid_until)) S.access.until = Date.parse(r.paid_until); after(); }
  });
  const f = S.free;
  if(f && f.token && !(a && a.src==="wl")) DD_PAY.wl.access(f.email, f.token).then(r=>{
    if(r.active === false){ S.free.end = Math.min(S.free.end, Date.now()); return after(); }
    if(r.free_end){ S.free.end = r.free_end; after(); }
  });
}
/* ссылка из письма «место закреплено»: #trial=<token>. Токен проверяет и активирует сервер */
function tryTrialHash(){
  const m = location.hash.match(/^#trial=([a-f0-9]{32,64})$/); if(!m) return false;
  history.replaceState(null, "", location.pathname + location.search);
  startTrial(m[1]).then(ok=>{ if(ok) F.shutter(openAppFlow); else show("site"); });
  return true;
}
(function boot(){
  if(tryRestoreHash() || tryTrialHash()) return;
  const h = location.hash.slice(1), lp = legalParse(h), pm = /^pay=(plus|pro)-(\d+)$/.exec(h);
  if(ENTRY==="app"){
    /* /app/: только приложение. Без доступа - оплата (Беларусь) или запись на сайте; основной экран без хэша в адресе */
    if(lp && legalOut(h)) return;
    if(lp) openLegal(lp.doc, lp.sec, false);
    else if(pm) openPay(pm[1], pm[2]);
    else if(S.pendingOrder && !hasAccess()) resumePay();
    else if(h==="pay") openPay(payPlan);
    else if(canEnter()) openAppFlow();
    else if(REGION.pay) openPay(payPlan);
    else goSite("join");
    if(GATED.includes(h) || SITE_ANCHORS.includes(h)) history.replaceState(null, "", location.pathname + location.search);
  }
  else if(ENTRY==="site"){
    /* сайт: приложение сам не открывает, даже если анкета пройдена - только кнопка «Открыть приложение» */
    if(lp) openLegal(lp.doc, lp.sec, false);
    else if(SPLIT && (pm || h==="pay" || GATED.includes(h))) return toApp(h);
    else { show("site"); if(SITE_ANCHORS.includes(h)) setTimeout(()=>scrollToId(h), 60); }
  }
  else if(lp) openLegal(lp.doc, lp.sec, false);
  else if(S.pendingOrder && !hasAccess()) resumePay();
  else if(h==="pay" || GATED.includes(h)) route(h);
  else if(canEnter() && !SITE_ANCHORS.includes(h)) openAppFlow();
  else if(freeOver() && !h){ show("site"); setTimeout(()=>scrollToId("pricing"), 60); }
  else { show("site"); if(SITE_ANCHORS.includes(h)) setTimeout(()=>scrollToId(h), 60); }
  openRecipeHash();
  recheckAccessOnBoot();
  geoRefreshIfGranted();
})();
